INSERT INTO `cms_pages` VALUES (1, 'Home', 'home', '<div class=\"prose prose-slate dark:prose-invert max-w-none w-full\" style=\"max-width: none !important; width: 100%;\"><!-- HERO SECTION -->\n<section class=\"w-full rounded-2xl overflow-hidden bg-white dark:bg-slate-800/80 border border-slate-200 dark:border-slate-700/60 shadow-sm mb-5\">\n<div class=\"py-12 sm:py-16 px-6 sm:px-10 lg:px-16 max-w-7xl mx-auto text-center\">\n<div class=\"space-y-5\">\n<p class=\"text-xs font-extrabold uppercase tracking-[0.2em] text-indigo-500 dark:text-indigo-400\" data-aos=\"zoom-in\" data-aos-duration=\"600\" data-aos-offset=\"80\" data-aos-easing=\"ease-out-cubic\" data-aos-once=\"true\">Welcome to THE Site Store Pro DEMO</p>\n<h1 class=\"text-3xl sm:text-5xl font-extrabold tracking-tight text-slate-900 dark:text-white max-w-4xl mx-auto leading-tight\" data-aos=\"fade-up\" data-aos-duration=\"600\" data-aos-delay=\"100\" data-aos-offset=\"40\" data-aos-easing=\"ease-out-cubic\" data-aos-once=\"true\">The Modern Platform for Serious eCommerce</h1>\n<div class=\"mx-auto rounded-2xl border border-slate-200 dark:border-slate-700/60 bg-slate-50/60 dark:bg-slate-800/40 px-6 py-5\" style=\"max-width: 700px;\" data-aos=\"fade-up\" data-aos-duration=\"600\" data-aos-delay=\"200\" data-aos-offset=\"40\" data-aos-easing=\"ease-out-cubic\" data-aos-once=\"true\">\n<p class=\"text-slate-500 dark:text-slate-300 text-base sm:text-lg leading-relaxed text-justify m-0\" style=\"text-align: justify;\">Built on Laravel 13 &mdash; a complete eCommerce &amp; CMS platform with a full site builder, dynamic page management, knowledge base, products, variants, built-in and expandable payment providers, support ticket system and a powerful admin panel. <strong>Everything you need to run a serious online store.</strong></p>\n</div>\n<!-- Button Group -->\n<div class=\"flex flex-wrap items-center justify-center gap-3 pt-2\" data-aos=\"fade-up\" data-aos-duration=\"600\" data-aos-delay=\"300\" data-aos-offset=\"40\" data-aos-easing=\"ease-out-cubic\" data-aos-once=\"true\"><!-- Browse Demo Store --> <a class=\"inline-flex items-center gap-2 px-5 py-2.5 bg-indigo-600 hover:bg-indigo-700 text-white text-sm font-bold rounded-xl shadow-md hover:shadow-lg transition-all duration-200 group\" title=\"Browse Demo Store\" href=\"[site_url]/shop\"> <svg class=\"w-4 h-4 shrink-0 group-hover:scale-110 transition-transform\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\">\n                            <path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M3 3h2l.4 2M7 13h10l4-8H5.4M7 13L5.4 5M7 13l-2.293 2.293c-.63.63-.184 1.707.707 1.707H17m0 0a2 2 0 100 4 2 2 0 000-4zm-8 2a2 2 0 11-4 0 2 2 0 014 0z\"></path>\n                        </svg> Browse Demo Store </a> <!-- View Documentation --> <a class=\"inline-flex items-center gap-2 px-5 py-2.5 bg-white dark:bg-slate-800 hover:bg-slate-50 dark:hover:bg-slate-700 text-slate-700 dark:text-slate-200 text-sm font-bold rounded-xl border border-slate-200 dark:border-slate-600 shadow-sm hover:shadow-md transition-all duration-200 group\" title=\"Site Store Pro Help Docs\" href=\"https://docs.sitestorepro.com/introduction\" target=\"_blank\" rel=\"noopener\"> <svg class=\"w-4 h-4 shrink-0 group-hover:scale-110 transition-transform text-slate-500 dark:text-slate-400\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\">\n                            <path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 6.253v13m0-13C10.832 5.477 9.246 5 7.5 5S4.168 5.477 3 6.253v13C4.168 18.477 5.754 18 7.5 18s3.332.477 4.5 1.253m0-13C13.168 5.477 14.754 5 16.5 5c1.747 0 3.332.477 4.5 1.253v13C19.832 18.477 18.247 18 16.5 18c-1.746 0-3.332.477-4.5 1.253\"></path>\n                        </svg> View Documentation </a> <!-- GitHub Download --> <a class=\"inline-flex items-center gap-2 px-5 py-2.5 bg-indigo-600 hover:bg-indigo-700 text-white text-sm font-bold rounded-xl shadow-md hover:shadow-lg transition-all duration-200 group\" title=\"Download Site Store Pro\" href=\"https://github.com/site-store-pro/laravel-ecommerce\" target=\"_blank\" rel=\"noopener\"> <svg class=\"w-4 h-4 shrink-0 group-hover:scale-110 transition-transform\" fill=\"currentColor\" viewBox=\"0 0 24 24\">\n                            <path fill-rule=\"evenodd\" d=\"M12 2C6.477 2 2 6.484 2 12.017c0 4.425 2.865 8.18 6.839 9.504.5.092.682-.217.682-.483 0-.237-.008-.868-.013-1.703-2.782.605-3.369-1.343-3.369-1.343-.454-1.158-1.11-1.466-1.11-1.466-.908-.62.069-.608.069-.608 1.003.07 1.531 1.032 1.531 1.032.892 1.53 2.341 1.088 2.91.832.092-.647.35-1.088.636-1.338-2.22-.253-4.555-1.113-4.555-4.951 0-1.093.39-1.988 1.029-2.688-.103-.253-.446-1.272.098-2.65 0 0 .84-.27 2.75 1.026A9.564 9.564 0 0112 6.844c.85.004 1.705.115 2.504.337 1.909-1.296 2.747-1.027 2.747-1.027.546 1.379.202 2.398.1 2.651.64.7 1.028 1.595 1.028 2.688 0 3.848-2.339 4.695-4.566 4.943.359.309.678.92.678 1.855 0 1.338-.012 2.419-.012 2.747 0 .268.18.58.688.482A10.019 10.019 0 0022 12.017C22 6.484 17.522 2 12 2z\" clip-rule=\"evenodd\"></path>\n                        </svg> GitHub Download </a></div>\n</div>\n</div>\n</section>\n<!-- BRANDS + BENEFITS SECTION -->\n<section id=\"brands\" class=\"w-full rounded-2xl overflow-hidden bg-slate-50 dark:bg-slate-900/60 border border-slate-200 dark:border-slate-700/60 mb-5\">\n<div class=\"py-10 px-6 sm:px-10 lg:px-16 max-w-7xl mx-auto\">\n<p class=\"text-center text-[11px] font-extrabold uppercase tracking-[0.18em] text-slate-400 dark:text-slate-500 mb-6\" data-aos=\"fade\" data-aos-duration=\"500\" data-aos-offset=\"60\" data-aos-easing=\"ease-out-cubic\" data-aos-once=\"true\">Trusted by Leading Brands</p>\n<div class=\"max-w-[900px] mx-auto mb-10\" data-aos=\"fade-up\" data-aos-duration=\"600\" data-aos-offset=\"60\" data-aos-easing=\"ease-out-cubic\" data-aos-once=\"true\">[plugin:brands-2026]</div>\n<!-- Divider -->\n<div class=\"border-t border-slate-200 dark:border-slate-700/60 mb-8\">&nbsp;</div>\n<!-- Benefits Grid -->\n<div class=\"grid grid-cols-1 sm:grid-cols-2 md:grid-cols-4 gap-4 max-w-5xl mx-auto text-left\"><a class=\"p-4 rounded-2xl bg-white dark:bg-slate-800/60 border border-slate-200 dark:border-slate-700/60 flex items-center gap-3 hover:border-indigo-400 dark:hover:border-indigo-500/70 hover:bg-indigo-50/60 dark:hover:bg-indigo-900/20 hover:shadow-md hover:-translate-y-0.5 transition-all duration-200 group\" href=\"[site_url]/shipping-policy\" data-aos=\"fade-up\" data-aos-duration=\"500\" data-aos-delay=\"0\" data-aos-offset=\"60\" data-aos-easing=\"ease-out-cubic\" data-aos-once=\"true\">\n<div class=\"w-10 h-10 rounded-xl bg-indigo-100 dark:bg-indigo-900/40 text-indigo-600 dark:text-indigo-400 flex items-center justify-center shrink-0 group-hover:scale-110 transition-transform\"><svg class=\"w-5 h-5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\">\n                            <path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M5 8h14M5 8a2 2 0 01-2-2V5a2 2 0 012-2h14a2 2 0 012 2v1a2 2 0 01-2 2M5 8v10a2 2 0 002 2h10a2 2 0 002-2V8m-9 4h4\"></path>\n                        </svg></div>\n<div>\n<h4 class=\"text-xs font-bold text-slate-900 dark:text-slate-100 group-hover:text-indigo-700 dark:group-hover:text-indigo-300 transition-colors\">Free Shipping</h4>\n<p class=\"text-[11px] text-slate-500 dark:text-slate-400\">On all orders over $50</p>\n</div>\n</a><a class=\"p-4 rounded-2xl bg-white dark:bg-slate-800/60 border border-slate-200 dark:border-slate-700/60 flex items-center gap-3 hover:border-emerald-400 dark:hover:border-emerald-500/70 hover:bg-emerald-50/60 dark:hover:bg-emerald-900/20 hover:shadow-md hover:-translate-y-0.5 transition-all duration-200 group\" href=\"[site_url]/returns-refunds-policy\" data-aos=\"fade-up\" data-aos-duration=\"500\" data-aos-delay=\"100\" data-aos-offset=\"60\" data-aos-easing=\"ease-out-cubic\" data-aos-once=\"true\">\n<div class=\"w-10 h-10 rounded-xl bg-emerald-100 dark:bg-emerald-900/40 text-emerald-600 dark:text-emerald-400 flex items-center justify-center shrink-0 group-hover:scale-110 transition-transform\"><svg class=\"w-5 h-5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\">\n                            <path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04A12.02 12.02 0 003 9c0 5.591 3.824 10.29 9 11.622 5.176-1.332 9-6.03 9-11.622 0-1.042-.133-2.052-.382-3.016z\"></path>\n                        </svg></div>\n<div>\n<h4 class=\"text-xs font-bold text-slate-900 dark:text-slate-100 group-hover:text-emerald-700 dark:group-hover:text-emerald-300 transition-colors\">Easy Returns</h4>\n<p class=\"text-[11px] text-slate-500 dark:text-slate-400\">30-day no-questions policy</p>\n</div>\n</a><a class=\"p-4 rounded-2xl bg-white dark:bg-slate-800/60 border border-slate-200 dark:border-slate-700/60 flex items-center gap-3 hover:border-amber-400 dark:hover:border-amber-500/70 hover:bg-amber-50/60 dark:hover:bg-amber-900/20 hover:shadow-md hover:-translate-y-0.5 transition-all duration-200 group\" href=\"[site_url]/section/downloads-media\" data-aos=\"fade-up\" data-aos-duration=\"500\" data-aos-delay=\"200\" data-aos-offset=\"60\" data-aos-easing=\"ease-out-cubic\" data-aos-once=\"true\">\n<div class=\"w-10 h-10 rounded-xl bg-amber-100 dark:bg-amber-900/40 text-amber-600 dark:text-amber-400 flex items-center justify-center shrink-0 group-hover:scale-110 transition-transform\"><svg class=\"w-5 h-5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\">\n                            <path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4\"></path>\n                        </svg></div>\n<div>\n<h4 class=\"text-xs font-bold text-slate-900 dark:text-slate-100 group-hover:text-amber-700 dark:group-hover:text-amber-300 transition-colors\">Instant Downloads</h4>\n<p class=\"text-[11px] text-slate-500 dark:text-slate-400\">eBooks, courses &amp; more</p>\n</div>\n</a><a class=\"p-4 rounded-2xl bg-white dark:bg-slate-800/60 border border-slate-200 dark:border-slate-700/60 flex items-center gap-3 hover:border-violet-400 dark:hover:border-violet-500/70 hover:bg-violet-50/60 dark:hover:bg-violet-900/20 hover:shadow-md hover:-translate-y-0.5 transition-all duration-200 group\" href=\"[site_url]/tickets/create\" data-aos=\"fade-up\" data-aos-duration=\"500\" data-aos-delay=\"300\" data-aos-offset=\"60\" data-aos-easing=\"ease-out-cubic\" data-aos-once=\"true\">\n<div class=\"w-10 h-10 rounded-xl bg-violet-100 dark:bg-violet-900/40 text-violet-600 dark:text-violet-400 flex items-center justify-center shrink-0 group-hover:scale-110 transition-transform\"><svg class=\"w-5 h-5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\">\n                            <path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M18.364 5.636l-3.536 3.536m0 5.656l3.536 3.536M9.172 9.172L5.636 5.636m3.536 9.192l-3.536 3.536M21 12a9 9 0 11-18 0 9 9 0 0118 0zm-5 0a4 4 0 11-8 0 4 4 0 018 0z\"></path>\n                        </svg></div>\n<div>\n<h4 class=\"text-xs font-bold text-slate-900 dark:text-slate-100 group-hover:text-violet-700 dark:group-hover:text-violet-300 transition-colors\">24/7 Support</h4>\n<p class=\"text-[11px] text-slate-500 dark:text-slate-400\">Real help, when you need it</p>\n</div>\n</a></div>\n</div>\n</section>\n<!-- FEATURED ITEMS SECTION -->\n<section class=\"w-full rounded-2xl overflow-hidden bg-white dark:bg-slate-800/80 border border-slate-200 dark:border-slate-700/60 shadow-sm mb-5\">\n<div class=\"py-10 px-6 sm:px-10 lg:px-16 max-w-7xl mx-auto\">\n<div class=\"text-center mb-8\" data-aos=\"fade-up\" data-aos-duration=\"600\" data-aos-offset=\"80\" data-aos-easing=\"ease-out-cubic\" data-aos-once=\"true\">\n<p class=\"text-xs font-extrabold uppercase tracking-[0.18em] text-indigo-500 dark:text-indigo-400 mb-1\">Handpicked For You</p>\n<h2 class=\"text-2xl sm:text-3xl font-extrabold text-slate-900 dark:text-white\">Featured Products</h2>\n<p class=\"mt-1.5 text-sm text-slate-500 dark:text-slate-400 max-w-xl mx-auto\">Our most popular items &mdash; curated by our team and loved by customers.</p>\n</div>\n<div data-aos=\"fade-up\" data-aos-duration=\"700\" data-aos-delay=\"100\" data-aos-offset=\"80\" data-aos-easing=\"ease-out-cubic\" data-aos-once=\"true\">[plugin:featured-items display=slider]</div>\n<div class=\"text-center mt-6\" data-aos=\"fade-up\" data-aos-duration=\"500\" data-aos-delay=\"150\" data-aos-offset=\"60\" data-aos-easing=\"ease-out-cubic\" data-aos-once=\"true\"><a class=\"inline-flex items-center gap-1.5 text-sm font-bold text-indigo-600 dark:text-indigo-400 hover:underline underline-offset-4 transition-all\" href=\"[site_url]/shop\"> View All Products &rarr; </a></div>\n</div>\n</section>\n<!-- CATEGORIES SECTION -->\n<section class=\"w-full rounded-2xl overflow-hidden bg-slate-50 dark:bg-slate-900/60 border border-slate-200 dark:border-slate-700/60 mb-5\">\n<div class=\"py-10 px-6 sm:px-10 lg:px-16 max-w-7xl mx-auto\">\n<div class=\"text-center mb-8\" data-aos=\"fade-up\" data-aos-duration=\"600\" data-aos-offset=\"80\" data-aos-easing=\"ease-out-cubic\" data-aos-once=\"true\">\n<p class=\"text-xs font-extrabold uppercase tracking-[0.18em] text-emerald-500 dark:text-emerald-400 mb-1\">Find What You Love</p>\n<h2 class=\"text-2xl sm:text-3xl font-extrabold text-slate-900 dark:text-white\">Shop By Category</h2>\n<p class=\"mt-1.5 text-sm text-slate-500 dark:text-slate-400 max-w-xl mx-auto\">Explore our full range across every department.</p>\n</div>\n<div data-aos=\"fade-up\" data-aos-duration=\"700\" data-aos-delay=\"100\" data-aos-offset=\"80\" data-aos-easing=\"ease-out-cubic\" data-aos-once=\"true\">[plugin:categories-2026 display=grid]</div>\n</div>\n</section>\n<!-- TESTIMONIALS SECTION -->\n<section class=\"w-full rounded-2xl overflow-hidden bg-white dark:bg-slate-800/80 border border-slate-200 dark:border-slate-700/60 shadow-sm\">\n<div class=\"py-10 px-6 sm:px-10 lg:px-16 max-w-7xl mx-auto\">\n<div class=\"text-center mb-8\" data-aos=\"fade-up\" data-aos-duration=\"600\" data-aos-offset=\"80\" data-aos-easing=\"ease-out-cubic\" data-aos-once=\"true\">\n<p class=\"text-xs font-extrabold uppercase tracking-[0.18em] text-violet-500 dark:text-violet-400 mb-1\">Real Customers, Real Results</p>\n<h2 class=\"text-2xl sm:text-3xl font-extrabold text-slate-900 dark:text-white\">What Our Customers Say</h2>\n<p class=\"mt-1.5 text-sm text-slate-500 dark:text-slate-400 max-w-xl mx-auto\">Thousands of happy customers trust us every day.</p>\n</div>\n<div data-aos=\"fade-up\" data-aos-duration=\"700\" data-aos-delay=\"100\" data-aos-offset=\"80\" data-aos-easing=\"ease-out-cubic\" data-aos-once=\"true\">[plugin:testimonials-2026]</div>\n</div>\n</section>\n</div>', 'Welcome', 'An integrated e-commerce and customer support platform with secure downloads, a CMS, shortcodes, and a knowledge base.', 'Home home Welcome An integrated e-commerce and customer support platform with secure downloads, a CMS, shortcodes, and a knowledge base. Welcome to THE Site Store Pro DEMO The Modern Platform for Serious eCommerce Built on Laravel 13 &mdash; a complete eCommerce &amp; CMS platform with a full site builder, dynamic page management, knowledge base, products, variants, built-in and expandable payment providers, support ticket system and a powerful admin panel. Everything you need to run a serious online store. Browse Demo Store View Documentation GitHub Download Trusted by Leading Brands &nbsp; Free Shipping On all orders over $50 Easy Returns 30-day no-questions policy Instant Downloads eBooks, courses &amp; more 24/7 Support Real help, when you need it Handpicked For You Featured Products Our most popular items &mdash; curated by our team and loved by customers. View All Products &rarr; Find What You Love Shop By Category Explore our full range across every department. Real Customers, Real Results What Our Customers Say Thousands of happy customers trust us every day.', 0, NULL, NULL, 0, NULL, NULL, '.main-sticky-offset {padding-top: 0px!important;}', '', NULL, NULL, NULL, NULL, 'local', 0, NULL, NULL, NULL, NULL, NULL, NULL, 'middle-center', NULL, '[plugin:slideshow-2026]', '320px', 1, 0, 1, 0, 1, 0, 1, '', '', NULL, 0, 0, 0, NULL, 0, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, '2026-07-22 12:49:40', '2026-08-10 22:27:52');
INSERT INTO `cms_pages` VALUES (2, 'About Us', 'about-us', '<div class=\"prose prose-slate max-w-none\" style=\"max-width: none !important; width: 100%;\">\n<h1>About Us</h1>\n<p>We are an online marketplace dedicated to bringing thoughtful digital products, carefully curated shippable gifts, and memorable event experiences to customers everywhere. Our focus is on making discovery, purchase, and delivery simple and reliable &mdash; whether you&rsquo;re downloading a digital item instantly, sending a gift to someone special, or booking an experience to remember.</p>\n<h2>Our Mission</h2>\n<p>To connect people with high-quality products and experiences through a convenient, transparent, and customer-first shopping experience. We aim to inspire moments of delight by combining great selection with attentive service.</p>\n<h2>What We Offer</h2>\n<ul>\n<li><strong>Digital items:</strong> E-books, downloadable assets, licenses, and other instantly deliverable products for immediate use.</li>\n<li><strong>Shippable gifts:</strong> Thoughtfully packaged physical items that can be sent to friends, family, and colleagues with care.</li>\n<li><strong>Events &amp; experiences:</strong> Tickets, workshops, and booked experiences designed to create lasting memories.</li>\n</ul>\n<h2>How It Works</h2>\n<ol>\n<li><strong>Browse:</strong> Explore curated collections and categories to find what fits your needs.</li>\n<li><strong>Purchase:</strong> Use our secure checkout to complete your order with multiple payment options.</li>\n<li><strong>Receive:</strong> Digital items are delivered instantly; physical gifts are carefully packed and shipped; event tickets are issued or confirmed by email.</li>\n<li><strong>Enjoy:</strong> Use your digital product, surprise someone with a gift, or attend the event.</li>\n</ol>\n<aside style=\"border-left: 4px solid #e2e8f0; padding-left: 1rem; margin: 1rem 0;\" aria-label=\"Customer commitment\"><strong>Our commitment:</strong> We prioritize product quality, transparent information, and responsive customer support so you can shop with confidence.</aside>\n<h2>Customer Care &amp; Security</h2>\n<p>Your privacy and security are important to us. We use industry-standard measures to protect payment and personal information, and our customer support team is available to help with questions about orders, downloads, shipping, or event details.</p>\n<h2>Shipping, Returns &amp; Cancellations</h2>\n<p>Shipping options and delivery times vary by product and destination. Digital items are generally available immediately after purchase. For shippable gifts and events, we provide clear timelines and instructions at checkout. We strive for flexible, fair policies and will work with you if something doesn&rsquo;t meet your expectations.</p>\n<h2>Quality &amp; Sustainability</h2>\n<p>We work with partners and vendors who share our standards for quality and responsible practices. Whenever possible we support sustainable packaging and thoughtful sourcing for physical goods.</p>\n<h2>Get Involved</h2>\n<p>We&rsquo;re always looking to improve. If you have feedback, partnership inquiries, or ideas for new products and events, we welcome your input. Reach out to our support team through the help center or the contact option in your account.</p>\n<p>Thank you for considering us for your digital downloads, thoughtful gifts, and event experiences. Explore our collections and upcoming events to find something that speaks to you.</p>\n</div>', 'About This Platform', 'Learn about this integrated e-commerce and support platform built with Laravel and Livewire.', 'About Us about us About This Platform Learn about this integrated e-commerce and support platform built with Laravel and Livewire. About Us We are an online marketplace dedicated to bringing thoughtful digital products, carefully curated shippable gifts, and memorable event experiences to customers everywhere. Our focus is on making discovery, purchase, and delivery simple and reliable &mdash; whether you&rsquo;re downloading a digital item instantly, sending a gift to someone special, or booking an experience to remember. Our Mission To connect people with high-quality products and experiences through a convenient, transparent, and customer-first shopping experience. We aim to inspire moments of delight by combining great selection with attentive service. What We Offer Digital items: E-books, downloadable assets, licenses, and other instantly deliverable products for immediate use. Shippable gifts: Thoughtfully packaged physical items that can be sent to friends, family, and colleagues with care. Events &amp; experiences: Tickets, workshops, and booked experiences designed to create lasting memories. How It Works Browse: Explore curated collections and categories to find what fits your needs. Purchase: Use our secure checkout to complete your order with multiple payment options. Receive: Digital items are delivered instantly; physical gifts are carefully packed and shipped; event tickets are issued or confirmed by email. Enjoy: Use your digital product, surprise someone with a gift, or attend the event. Our commitment: We prioritize product quality, transparent information, and responsive customer support so you can shop with confidence. Customer Care &amp; Security Your privacy and security are important to us. We use industry-standard measures to protect payment and personal information, and our customer support team is available to help with questions about orders, downloads, shipping, or event details. Shipping, Returns &amp; Cancellations Shipping options and delivery times vary by product and destination. Digital items are generally available immediately after purchase. For shippable gifts and events, we provide clear timelines and instructions at checkout. We strive for flexible, fair policies and will work with you if something doesn&rsquo;t meet your expectations. Quality &amp; Sustainability We work with partners and vendors who share our standards for quality and responsible practices. Whenever possible we support sustainable packaging and thoughtful sourcing for physical goods. Get Involved We&rsquo;re always looking to improve. If you have feedback, partnership inquiries, or ideas for new products and events, we welcome your input. Reach out to our support team through the help center or the contact option in your account. Thank you for considering us for your digital downloads, thoughtful gifts, and event experiences. Explore our collections and upcoming events to find something that speaks to you.', 0, NULL, NULL, 0, NULL, NULL, '', '', NULL, NULL, NULL, NULL, 'local', 0, NULL, NULL, NULL, NULL, NULL, NULL, 'middle-center', NULL, NULL, '320px', 1, 0, 1, 0, 1, 0, 1, '', '', NULL, 0, 1, 0, NULL, 0, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, '2026-07-22 12:49:40', '2026-08-05 19:35:35');
INSERT INTO `cms_pages` VALUES (5, 'Terms of Service', 'terms', '<div class=\"prose prose-slate max-w-none\" style=\"max-width: none !important; width: 100%;\">\n<h2>Terms of Service</h2>\n<p>These Terms of Service (\"Terms\") govern your access to and use of this website and any services, products, digital downloads, and event registrations made available through it. By accessing or using the platform, you agree to be bound by these Terms. If you do not agree, do not use the site or make purchases.</p>\n<h3>1. Changes to These Terms</h3>\n<p>We may amend these Terms at any time. Changes become effective when posted on the site. Your continued use after changes are posted constitutes acceptance of the updated Terms. It is your responsibility to review these Terms periodically.</p>\n<h3>2. Eligibility</h3>\n<p>You must be at least 18 years old (or the age of majority in your jurisdiction) and have the legal capacity to enter into contracts to use the site and make purchases. By placing an order, you represent that you meet these requirements.</p>\n<h3>3. Account Registration and Security</h3>\n<p>Some features require an account. You agree to provide accurate, current, and complete information and to keep your account credentials secure. You are responsible for all activity under your account. Notify support immediately of any unauthorized use or security breach.</p>\n<h3>4. Purchases, Pricing, and Payment</h3>\n<p>All orders are subject to product availability and confirmation of payment. Prices shown are in the currency indicated and do not include applicable taxes and shipping unless stated. We reserve the right to correct pricing errors and to refuse or cancel orders placed with incorrect prices. Payment methods accepted are displayed at checkout.</p>\n<h4>Taxes and Duties</h4>\n<p>Buyers are responsible for any applicable taxes, duties, or customs fees for international shipments. We may collect tax at checkout where required by law.</p>\n<h3>5. Shipping and Delivery (Shippable Products)</h3>\n<p>Shipping options, carriers, and delivery estimates are provided at checkout. Estimated delivery times are not guaranteed and are subject to carrier schedules and customs processing for international orders. Risk of loss and title for physical goods pass to you when the carrier accepts the goods for shipment.</p>\n<p>We are not responsible for delays caused by carrier issues, customs, or circumstances beyond our control. If a shipment is lost or damaged in transit, please contact support so we can assist with carrier claims.</p>\n<h3>6. Returns, Refunds, and Exchanges</h3>\n<p>Our return and refund practices differ by product type. The following describes general policies; specific product listings may include additional terms.</p>\n<h4>Physical Goods</h4>\n<ul>\n<li>Physical goods may be returned within 30 days of purchase if unused and in original packaging, unless otherwise stated.</li>\n<li>You are generally responsible for return shipping costs unless the return is due to our error (e.g., wrong or defective item).</li>\n<li>Returned items must be accompanied by proof of purchase. Refunds will be issued to the original payment method after we inspect the returned item. Refund processing may take several business days.</li>\n<li>We may refuse returns that do not meet the above conditions or are returned outside the return period.</li>\n</ul>\n<h4>Digital Products and Downloads</h4>\n<ul>\n<li>Digital products and downloadable files are typically delivered immediately upon order confirmation.</li>\n<li>Digital purchases are generally non-refundable once delivered, except where required by law or where a technical delivery failure prevents access to the product.</li>\n<li>If you experience download or access issues, open a support ticket with details so we can assist. If a refund is approved for a digital product, you must cease use and delete any copies; license access may be revoked.</li>\n</ul>\n<h4>Event Registrations and Tickets</h4>\n<ul>\n<li>Event registrations are subject to the event&rsquo;s specific cancellation, transfer, and refund policy. Check the event details before purchase.</li>\n<li>Refunds for event registrations may be available within a limited window prior to the event start date; otherwise tickets may be non-refundable. Transfers of registration to another person may be permitted subject to availability and fees.</li>\n<li>If an event is canceled by the organizer, you will be notified and given options such as refund, credit, or transfer to a rescheduled date. We are not responsible for travel or other expenses you may incur.</li>\n</ul>\n<h4>How to Request a Return or Refund</h4>\n<p>To request a return or report a delivery or download issue, contact customer support with your order number, the item(s) affected, and a description of the problem. Provide any requested documentation (photos of damaged items, error messages, etc.). We will review and respond within a reasonable timeframe.</p>\n<div style=\"border-left: 4px solid #e2e8f0; padding: 10px 15px; background: #f8fafc;\"><strong>Note:</strong> Approved refunds for goods are issued to the original payment method. Refunds may take several business days to appear on your statement, depending on your payment provider.</div>\n<h3>7. Licenses, Usage Rights, and Restrictions (Digital Content)</h3>\n<p>Unless explicitly stated otherwise, purchases of digital products grant you a limited, non-exclusive, non-transferable, revocable license to use the content for your personal or internal business use only. Unless permitted by separate agreement, you may not:</p>\n<ul>\n<li>Resell, sublicense, distribute, or make available the digital product to third parties;</li>\n<li>Remove or obscure any proprietary notices or marks;</li>\n<li>Reverse engineer, decompile, or attempt to extract source code or underlying data;</li>\n<li>Use the content in a manner that violates applicable laws or third-party rights.</li>\n</ul>\n<h3>8. Event Participation and Code of Conduct</h3>\n<p>By registering for and attending events, you agree to comply with the event&rsquo;s rules and directions from organizers and staff. Unruly, illegal, or unsafe behavior may result in removal without refund. You are responsible for your own travel, lodging, and personal expenses unless otherwise specified.</p>\n<h3>9. User Content and Submissions</h3>\n<p>If you submit reviews, comments, or other content, you grant a non-exclusive, royalty-free, worldwide license to use, reproduce, modify, and display that content in connection with the site and its promotion. Do not submit content you do not own or have permission to use. We may remove content at our discretion.</p>\n<h3>10. Intellectual Property</h3>\n<p>All site content, including text, graphics, logos, images, software, and digital products, is protected by copyright and other intellectual property laws. Other than the limited license expressly granted above, we retain all rights, title, and interest in our content.</p>\n<h3>11. Third-Party Links and Services</h3>\n<p>The site may contain links to third-party websites, products, or services. We do not control and are not responsible for the content or practices of third parties. Links do not imply endorsement. Use third-party services at your own risk and review their terms and privacy policies.</p>\n<h3>12. Warranties and Disclaimers</h3>\n<p>The site and all products and services are provided \"as is\" and \"as available\" without warranties of any kind, whether express or implied. To the fullest extent permitted by law, we disclaim all warranties, including merchantability, fitness for a particular purpose, and non-infringement. We do not warrant uninterrupted or error-free operation, or that products meet your requirements.</p>\n<h3>13. Limitation of Liability</h3>\n<p>To the maximum extent permitted by law, in no event will we be liable for indirect, incidental, consequential, special, or exemplary damages arising from or related to your use of the site or products, even if advised of the possibility of such damages. Our aggregate liability for any claims related to your use of the site or purchase of products is limited to the amount you paid for the specific product or service that gives rise to the claim.</p>\n<h3>14. Indemnification</h3>\n<p>You agree to indemnify and hold harmless us, our affiliates, and our respective officers, directors, employees, and agents from any claims, liabilities, damages, losses, and expenses (including reasonable attorneys&rsquo; fees) arising from your breach of these Terms, your violation of applicable law, or your use of the site.</p>\n<h3>15. Termination</h3>\n<p>We may suspend or terminate your access to the site and services at any time, with or without notice, for conduct that we believe violates these Terms or is harmful to other users or third parties. Termination does not affect rights and obligations that arose prior to termination.</p>\n<h3>16. Governing Law and Dispute Resolution</h3>\n<p>These Terms are governed by the laws of the jurisdiction specified in our legal notices or as otherwise required by applicable law. Disputes will be handled in the courts located in that jurisdiction unless alternative dispute resolution (such as arbitration) is specified. If you are a consumer, local consumer protection laws may apply.</p>\n<h3>17. Force Majeure</h3>\n<p>We are not liable for failure to perform due to causes beyond our reasonable control, including but not limited to acts of God, natural disasters, pandemics, labor disputes, acts of government, or failures of telecommunications or internet providers.</p>\n<h3>18. Promotions, Coupons, and Gift Cards</h3>\n<p>Promotional offers, coupon codes, and gift cards are subject to separate terms and expiration dates. Promotions cannot be combined unless explicitly allowed. Abuse of promotions may result in cancellation of orders or accounts.</p>\n<h3>19. Privacy</h3>\n<p>We collect and process personal information in accordance with our [page:17 label=\"Privacy Statement\"]. By using the site, you consent to such collection and processing. Review our [page:17 label=\"Privacy Statement\"] for details about how we handle personal data.</p>\n<h3>20. Contact and Support</h3>\n<p>If you have questions about these Terms, need assistance with an order, or need to report a problem with a digital delivery, please [page:16 label=\"Contact Us\"]. Include your order number and a clear description of the issue for faster assistance.</p>\n<p>By placing an order or using the site, you acknowledge that you have read, understood, and agree to these Terms of Service.</p>\n</div>', 'Terms of Service', 'Terms of service governing purchases, digital downloads, and support ticket policies.', 'Terms of Service terms Terms of Service Terms of service governing purchases, digital downloads, and support ticket policies. Terms of Service These Terms of Service (\"Terms\") govern your access to and use of this website and any services, products, digital downloads, and event registrations made available through it. By accessing or using the platform, you agree to be bound by these Terms. If you do not agree, do not use the site or make purchases. 1. Changes to These Terms We may amend these Terms at any time. Changes become effective when posted on the site. Your continued use after changes are posted constitutes acceptance of the updated Terms. It is your responsibility to review these Terms periodically. 2. Eligibility You must be at least 18 years old (or the age of majority in your jurisdiction) and have the legal capacity to enter into contracts to use the site and make purchases. By placing an order, you represent that you meet these requirements. 3. Account Registration and Security Some features require an account. You agree to provide accurate, current, and complete information and to keep your account credentials secure. You are responsible for all activity under your account. Notify support immediately of any unauthorized use or security breach. 4. Purchases, Pricing, and Payment All orders are subject to product availability and confirmation of payment. Prices shown are in the currency indicated and do not include applicable taxes and shipping unless stated. We reserve the right to correct pricing errors and to refuse or cancel orders placed with incorrect prices. Payment methods accepted are displayed at checkout. Taxes and Duties Buyers are responsible for any applicable taxes, duties, or customs fees for international shipments. We may collect tax at checkout where required by law. 5. Shipping and Delivery (Shippable Products) Shipping options, carriers, and delivery estimates are provided at checkout. Estimated delivery times are not guaranteed and are subject to carrier schedules and customs processing for international orders. Risk of loss and title for physical goods pass to you when the carrier accepts the goods for shipment. We are not responsible for delays caused by carrier issues, customs, or circumstances beyond our control. If a shipment is lost or damaged in transit, please contact support so we can assist with carrier claims. 6. Returns, Refunds, and Exchanges Our return and refund practices differ by product type. The following describes general policies; specific product listings may include additional terms. Physical Goods Physical goods may be returned within 30 days of purchase if unused and in original packaging, unless otherwise stated. You are generally responsible for return shipping costs unless the return is due to our error (e.g., wrong or defective item). Returned items must be accompanied by proof of purchase. Refunds will be issued to the original payment method after we inspect the returned item. Refund processing may take several business days. We may refuse returns that do not meet the above conditions or are returned outside the return period. Digital Products and Downloads Digital products and downloadable files are typically delivered immediately upon order confirmation. Digital purchases are generally non-refundable once delivered, except where required by law or where a technical delivery failure prevents access to the product. If you experience download or access issues, open a support ticket with details so we can assist. If a refund is approved for a digital product, you must cease use and delete any copies; license access may be revoked. Event Registrations and Tickets Event registrations are subject to the event&rsquo;s specific cancellation, transfer, and refund policy. Check the event details before purchase. Refunds for event registrations may be available within a limited window prior to the event start date; otherwise tickets may be non-refundable. Transfers of registration to another person may be permitted subject to availability and fees. If an event is canceled by the organizer, you will be notified and given options such as refund, credit, or transfer to a rescheduled date. We are not responsible for travel or other expenses you may incur. How to Request a Return or Refund To request a return or report a delivery or download issue, contact customer support with your order number, the item(s) affected, and a description of the problem. Provide any requested documentation (photos of damaged items, error messages, etc.). We will review and respond within a reasonable timeframe. Note: Approved refunds for goods are issued to the original payment method. Refunds may take several business days to appear on your statement, depending on your payment provider. 7. Licenses, Usage Rights, and Restrictions (Digital Content) Unless explicitly stated otherwise, purchases of digital products grant you a limited, non-exclusive, non-transferable, revocable license to use the content for your personal or internal business use only. Unless permitted by separate agreement, you may not: Resell, sublicense, distribute, or make available the digital product to third parties; Remove or obscure any proprietary notices or marks; Reverse engineer, decompile, or attempt to extract source code or underlying data; Use the content in a manner that violates applicable laws or third-party rights. 8. Event Participation and Code of Conduct By registering for and attending events, you agree to comply with the event&rsquo;s rules and directions from organizers and staff. Unruly, illegal, or unsafe behavior may result in removal without refund. You are responsible for your own travel, lodging, and personal expenses unless otherwise specified. 9. User Content and Submissions If you submit reviews, comments, or other content, you grant a non-exclusive, royalty-free, worldwide license to use, reproduce, modify, and display that content in connection with the site and its promotion. Do not submit content you do not own or have permission to use. We may remove content at our discretion. 10. Intellectual Property All site content, including text, graphics, logos, images, software, and digital products, is protected by copyright and other intellectual property laws. Other than the limited license expressly granted above, we retain all rights, title, and interest in our content. 11. Third-Party Links and Services The site may contain links to third-party websites, products, or services. We do not control and are not responsible for the content or practices of third parties. Links do not imply endorsement. Use third-party services at your own risk and review their terms and privacy policies. 12. Warranties and Disclaimers The site and all products and services are provided \"as is\" and \"as available\" without warranties of any kind, whether express or implied. To the fullest extent permitted by law, we disclaim all warranties, including merchantability, fitness for a particular purpose, and non-infringement. We do not warrant uninterrupted or error-free operation, or that products meet your requirements. 13. Limitation of Liability To the maximum extent permitted by law, in no event will we be liable for indirect, incidental, consequential, special, or exemplary damages arising from or related to your use of the site or products, even if advised of the possibility of such damages. Our aggregate liability for any claims related to your use of the site or purchase of products is limited to the amount you paid for the specific product or service that gives rise to the claim. 14. Indemnification You agree to indemnify and hold harmless us, our affiliates, and our respective officers, directors, employees, and agents from any claims, liabilities, damages, losses, and expenses (including reasonable attorneys&rsquo; fees) arising from your breach of these Terms, your violation of applicable law, or your use of the site. 15. Termination We may suspend or terminate your access to the site and services at any time, with or without notice, for conduct that we believe violates these Terms or is harmful to other users or third parties. Termination does not affect rights and obligations that arose prior to termination. 16. Governing Law and Dispute Resolution These Terms are governed by the laws of the jurisdiction specified in our legal notices or as otherwise required by applicable law. Disputes will be handled in the courts located in that jurisdiction unless alternative dispute resolution (such as arbitration) is specified. If you are a consumer, local consumer protection laws may apply. 17. Force Majeure We are not liable for failure to perform due to causes beyond our reasonable control, including but not limited to acts of God, natural disasters, pandemics, labor disputes, acts of government, or failures of telecommunications or internet providers. 18. Promotions, Coupons, and Gift Cards Promotional offers, coupon codes, and gift cards are subject to separate terms and expiration dates. Promotions cannot be combined unless explicitly allowed. Abuse of promotions may result in cancellation of orders or accounts. 19. Privacy We collect and process personal information in accordance with our . By using the site, you consent to such collection and processing. Review our for details about how we handle personal data. 20. Contact and Support If you have questions about these Terms, need assistance with an order, or need to report a problem with a digital delivery, please . Include your order number and a clear description of the issue for faster assistance. By placing an order or using the site, you acknowledge that you have read, understood, and agree to these Terms of Service.', 0, NULL, NULL, 0, NULL, NULL, '', '', NULL, NULL, NULL, NULL, 'local', 0, NULL, NULL, NULL, NULL, NULL, NULL, 'middle-center', NULL, NULL, '320px', 1, 0, 1, 0, 1, 0, 1, '', '', NULL, 0, 1, 0, NULL, 0, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, '2026-07-22 12:49:40', '2026-08-05 19:33:34');
INSERT INTO `cms_pages` VALUES (7, 'Search Results', 'search', '[plugin:live-search-2026 mode=results]', 'Search Results', 'Multi-content search results across products, CMS pages, knowledge base articles, and customer testimonials.', NULL, 0, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'local', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '320px', 1, 0, 1, 0, 1, 0, 1, NULL, NULL, NULL, 0, 0, 0, NULL, 0, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, '2026-07-22 12:49:40', '2026-07-22 12:49:40');
INSERT INTO `cms_pages` VALUES (13, 'Webinar & Guidebook Sample Post Purchase Page', 'webinar-guidebook-ordered', '<div class=\"prose prose-slate max-w-none\" style=\"max-width: none !important; width: 100%;\">\n<h1>Secure Video Access &amp; Embedding</h1>\n<p>This page contains purchased content and is protected by access controls (password and/or order verification). The sample below uses a public Vimeo demo for demonstration only. For production, choose a secure delivery method that matches your privacy and streaming requirements.</p>\n<p>[code-embed:1]</p>\n<h2>Embedding options</h2>\n<ul>\n<li><strong>Hosted video provider (recommended for most cases) using the CODE EMBED feature,</strong><br>Use a provider such as Vimeo or Wistia and enable domain-level embed restrictions so the video plays only on your site. These providers also offer privacy, analytics, and adaptive streaming out of the box.</li>\n<li><strong>Local or s3 signed URLs (high security) - Using the CMS Downloads Feature</strong><br>Store files on local drive or in S3 and deliver using time-limited signed URLs. This prevents unauthorized downloads and direct linking.</li>\n</ul>\n<h2>How to implement</h2>\n<ol>\n<li>Ensure the page enforces password and order verification before rendering the player.</li>\n<li>Choose a hosting method (hosted provider, S3 + CDN, or CMS protected files) based on your security needs and budget.</li>\n<li>Configure access controls:\n<ul>\n<li>Provider: enable domain-level restrictions and private links.</li>\n<li>S3/CDN: configure signed URLs and short expirations.</li>\n<li>CMS: enable file gating tied to orders or user sessions.</li>\n</ul>\n</li>\n<li>Embed the player:\n<ul>\n<li>Use the provider&rsquo;s embed code.</li>\n<li>Or insert the CMS downloads/embed component to stream protected files.</li>\n</ul>\n</li>\n<li>This page is set to be \'<strong>Exclude From Search</strong>\' under the publishing options which is the recommended setting for secured (gated) pages.</li>\n<li>Test thoroughly in staging to prevent unauthorized access and sharing of your content &mdash; confirm the video only plays from allowed domain(s) and that only the purchased users can view and/or with an access code.</li>\n</ol>\n</div>', 'Webinar & Guidebook Sample Post Purchase Page', '', '', 1, NULL, NULL, 1, 'demo12345#', 15, '', '', NULL, NULL, NULL, NULL, 'local', 0, NULL, NULL, NULL, NULL, NULL, NULL, 'middle-center', NULL, NULL, '320px', 1, 1, 1, 0, 1, 0, 1, '', '', NULL, 0, 0, 0, NULL, 0, NULL, NULL, NULL, NULL, 1, NULL, NULL, 'admin@visperity.app', 'X5LvXKvyxBbfZGD!', NULL, 'https://d23w3zagfzgqcb.cloudfront.net', '2026-07-26 13:12:45', '2026-08-02 14:01:17');
INSERT INTO `cms_pages` VALUES (16, 'Contact Us', 'contact', '<div class=\"prose prose-slate max-w-none\" style=\"max-width: none !important; width: 100%;\">\n<p style=\"text-align: center;\">Please complete the form below to contact is via email:</p>\n<div style=\"width: 100%; max-width: 600px; margin: 0 auto;\">[cms-form id=1]</div>\n<p>&nbsp;</p>\n</div>', 'Contact', '', 'Contact Us contact Contact Please complete the form below to contact is via email: &nbsp;', 0, NULL, NULL, 0, NULL, NULL, '', '', NULL, NULL, NULL, NULL, 'local', 0, NULL, NULL, NULL, NULL, NULL, NULL, 'middle-center', NULL, NULL, '320px', 1, 0, 1, 0, 1, 0, 1, '', '', NULL, 0, 1, 0, NULL, 0, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, '2026-07-31 01:12:50', '2026-08-05 19:27:03');
INSERT INTO `cms_pages` VALUES (17, 'Online Privacy Statement', 'privacy-policy', '<div class=\"prose prose-slate max-w-none\">\n<h1>Privacy Policy</h1>\n<p>This Privacy Policy explains how personal information is collected, used, and shared when you visit or make a purchase from this online store (the \"Site\"). By using the Site, you agree to the collection and use of information in accordance with this policy.</p>\n<h2>Information We Collect</h2>\n<p>We collect information you provide directly to us and information that is automatically collected when you interact with the Site.</p>\n<h3>Order Information</h3>\n<p>When you place an order, we may collect personal details necessary to process and fulfill that order, including:</p>\n<ul>\n<li>Name</li>\n<li>Billing and shipping address</li>\n<li>Payment details (processed via third-party payment providers)</li>\n<li>Email address and phone number</li>\n<li>Order history and preferences</li>\n</ul>\n<h3>Device and Usage Information</h3>\n<p>We automatically collect certain information about your device and how you interact with the Site. This may include:</p>\n<ul>\n<li>IP address, browser type, and device identifiers</li>\n<li>Pages viewed, products viewed, search terms, and referral sources</li>\n<li>Cookie and similar tracking data</li>\n<li>Log files, timestamps, and interaction events</li>\n</ul>\n<h2>How We Use Your Information</h2>\n<p>We use the information we collect for purposes including:</p>\n<ul>\n<li>Processing and fulfilling orders, including payment processing and shipping</li>\n<li>Communicating about orders, updates, promotions, and customer service</li>\n<li>Detecting and preventing fraud and other prohibited or illegal activities</li>\n<li>Improving and optimizing the Site, products, and services</li>\n<li>Personalizing content and marketing, subject to your choices and applicable law</li>\n</ul>\n<h2>Sharing and Disclosure</h2>\n<p>We may share personal information with third parties in the following circumstances:</p>\n<ul>\n<li>Service providers who perform services on our behalf (payment processors, shipping carriers, hosting and analytics providers)</li>\n<li>When required by law or to respond to lawful requests such as subpoenas or court orders</li>\n<li>To protect the rights, property, or safety of the Site, its users, or the public</li>\n<li>In connection with a merger, acquisition, or sale of assets (with notice to users as required by law)</li>\n</ul>\n<p>Third-party analytics and advertising partners may collect information about your use of the Site. For example, we may use analytics services that collect information about visits to an online property. You can learn more about third-party analytics and opt-out tools at the providers&rsquo; sites.</p>\n<h2>Cookies and Tracking Technologies</h2>\n<p>We use cookies and similar technologies (such as web beacons, tags, and pixels) to recognize your device, remember preferences, analyze site traffic, and provide relevant offers. Cookies may be first-party or provided by third parties. You can usually control cookies through your browser settings and opt-out mechanisms. For information about cookies and how to disable them, see allaboutcookies.org.</p>\n<h2>Do Not Track</h2>\n<p>Some browsers transmit \"Do Not Track\" signals. At this time, the Site does not automatically change its data collection and use practices in response to Do Not Track signals.</p>\n<h2>Your Rights</h2>\n<p>Your rights regarding your personal information may vary depending on your jurisdiction. The following are commonly available rights; they may be subject to certain requirements and exceptions under applicable law:</p>\n<ul>\n<li>Access: Request a copy of personal information we hold about you</li>\n<li>Correction: Request correction of inaccurate or incomplete information</li>\n<li>Deletion: Request deletion of personal information, subject to legal and contractual retention requirements</li>\n<li>Objection/Restriction: Object to or request restrictions on particular processing activities</li>\n<li>Data portability: Request a machine-readable copy of information you provided</li>\n<li>Opt-out: Where applicable, opt out of certain uses or sharing of personal information for marketing or sales</li>\n</ul>\n<p>To exercise these rights, use the contact options provided on the Site. We may ask you to verify your identity before responding to requests.</p>\n<h2>Data Retention</h2>\n<p>We retain personal information as long as necessary to provide our services, comply with legal obligations, resolve disputes, and enforce agreements. Order and transaction records may be retained for accounting, tax, and legal purposes even if you request deletion.</p>\n<h2>Security</h2>\n<p>We implement administrative, technical, and physical safeguards designed to protect personal information. However, no transmission over the internet or storage system is completely secure. We cannot guarantee absolute security of information.</p>\n<h2>Children</h2>\n<p>The Site is not intended for individuals under the age of 18. We do not knowingly collect personal information from children under the applicable minimum age. If you believe we have collected information from a child, please use the Site&rsquo;s contact methods to notify us so we can delete the information as required by law.</p>\n<h2>Changes to This Policy</h2>\n<p>We may update this Privacy Policy from time to time to reflect changes in our practices or legal requirements. We will post the updated policy on the Site with a revised effective date. Continued use of the Site after changes are posted constitutes acceptance of the updated policy.</p>\n<h2>Contact</h2>\n<p>If you have questions, concerns, or wish to exercise your rights under this policy, please use the contact channels provided on the Site. We will respond in accordance with applicable law.</p>\n</div>', 'Online Privacy Statement', '', 'Online Privacy Statement privacy policy Online Privacy Statement Privacy Policy This Privacy Policy explains how personal information is collected, used, and shared when you visit or make a purchase from this online store (the \"Site\"). By using the Site, you agree to the collection and use of information in accordance with this policy. Information We Collect We collect information you provide directly to us and information that is automatically collected when you interact with the Site. Order Information When you place an order, we may collect personal details necessary to process and fulfill that order, including: Name Billing and shipping address Payment details (processed via third-party payment providers) Email address and phone number Order history and preferences Device and Usage Information We automatically collect certain information about your device and how you interact with the Site. This may include: IP address, browser type, and device identifiers Pages viewed, products viewed, search terms, and referral sources Cookie and similar tracking data Log files, timestamps, and interaction events How We Use Your Information We use the information we collect for purposes including: Processing and fulfilling orders, including payment processing and shipping Communicating about orders, updates, promotions, and customer service Detecting and preventing fraud and other prohibited or illegal activities Improving and optimizing the Site, products, and services Personalizing content and marketing, subject to your choices and applicable law Sharing and Disclosure We may share personal information with third parties in the following circumstances: Service providers who perform services on our behalf (payment processors, shipping carriers, hosting and analytics providers) When required by law or to respond to lawful requests such as subpoenas or court orders To protect the rights, property, or safety of the Site, its users, or the public In connection with a merger, acquisition, or sale of assets (with notice to users as required by law) Third-party analytics and advertising partners may collect information about your use of the Site. For example, we may use analytics services that collect information about visits to an online property. You can learn more about third-party analytics and opt-out tools at the providers&rsquo; sites. Cookies and Tracking Technologies We use cookies and similar technologies (such as web beacons, tags, and pixels) to recognize your device, remember preferences, analyze site traffic, and provide relevant offers. Cookies may be first-party or provided by third parties. You can usually control cookies through your browser settings and opt-out mechanisms. For information about cookies and how to disable them, see allaboutcookies.org. Do Not Track Some browsers transmit \"Do Not Track\" signals. At this time, the Site does not automatically change its data collection and use practices in response to Do Not Track signals. Your Rights Your rights regarding your personal information may vary depending on your jurisdiction. The following are commonly available rights; they may be subject to certain requirements and exceptions under applicable law: Access: Request a copy of personal information we hold about you Correction: Request correction of inaccurate or incomplete information Deletion: Request deletion of personal information, subject to legal and contractual retention requirements Objection/Restriction: Object to or request restrictions on particular processing activities Data portability: Request a machine-readable copy of information you provided Opt-out: Where applicable, opt out of certain uses or sharing of personal information for marketing or sales To exercise these rights, use the contact options provided on the Site. We may ask you to verify your identity before responding to requests. Data Retention We retain personal information as long as necessary to provide our services, comply with legal obligations, resolve disputes, and enforce agreements. Order and transaction records may be retained for accounting, tax, and legal purposes even if you request deletion. Security We implement administrative, technical, and physical safeguards designed to protect personal information. However, no transmission over the internet or storage system is completely secure. We cannot guarantee absolute security of information. Children The Site is not intended for individuals under the age of 18. We do not knowingly collect personal information from children under the applicable minimum age. If you believe we have collected information from a child, please use the Site&rsquo;s contact methods to notify us so we can delete the information as required by law. Changes to This Policy We may update this Privacy Policy from time to time to reflect changes in our practices or legal requirements. We will post the updated policy on the Site with a revised effective date. Continued use of the Site after changes are posted constitutes acceptance of the updated policy. Contact If you have questions, concerns, or wish to exercise your rights under this policy, please use the contact channels provided on the Site. We will respond in accordance with applicable law.', 0, NULL, NULL, 0, NULL, NULL, '', '', NULL, NULL, NULL, NULL, 'local', 0, NULL, NULL, NULL, NULL, NULL, NULL, 'middle-center', NULL, NULL, '320px', 1, 0, 1, 0, 1, 0, 1, '', '', NULL, 1, 1, 1, NULL, 0, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-05 19:21:50', '2026-08-05 19:28:20');
INSERT INTO `cms_pages` VALUES (18, 'Frequently Asked Questions', 'faqs', '<div class=\"prose prose-slate max-w-none\" style=\"max-width: none !important; width: 100%;\">\n<p style=\"text-align: center;\">&nbsp;</p>\n</div>\n<p style=\"text-align: center;\">[plugin:faqs-2026 show_header=0]</p>\n<p>&nbsp;</p>', 'Frequently Asked Questions', '', 'Frequently Asked Questions faqs Frequently Asked Questions &nbsp; &nbsp;', 0, NULL, NULL, 0, NULL, NULL, '', '', NULL, NULL, NULL, NULL, 'local', 0, NULL, NULL, NULL, NULL, NULL, NULL, 'middle-center', NULL, NULL, '320px', 1, 0, 1, 0, 1, 0, 1, '', '', NULL, 0, 1, 0, NULL, 0, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-05 19:50:12', '2026-08-05 21:42:54');
INSERT INTO `cms_pages` VALUES (19, 'Check Order Status', 'check-order-status', '<div class=\"prose prose-slate max-w-none\" style=\"max-width: none !important; width: 100%;\">\n<p style=\"text-align: center;\">&nbsp;</p>\n</div>\n<p style=\"text-align: center;\">[plugin:order-tracker-2026]</p>\n<p>&nbsp;</p>', 'Check Order Status', 'Check Order status', 'Check Order Status check order status Check Order Status Check Order status &nbsp; &nbsp;', 0, NULL, NULL, 0, NULL, NULL, '', '', NULL, NULL, NULL, NULL, 'local', 0, NULL, NULL, NULL, NULL, NULL, NULL, 'middle-center', NULL, NULL, '320px', 1, 0, 1, 0, 1, 0, 1, '', '', NULL, 0, 0, 0, NULL, 0, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-05 21:45:38', '2026-08-05 21:46:14');
INSERT INTO `cms_pages` VALUES (20, 'Shipping Policy', 'shipping-policy', '<div class=\"prose prose-slate max-w-none\" style=\"max-width: none !important; width: 100%;\">\n<p>This shipping policy explains how orders are processed and shipped, the carriers we use, delivery estimates, and options for local pickup. Shipping practices and timelines may vary by carrier, product, and destination.</p>\n<h2>Order processing</h2>\n<p>Most orders are processed within 1&ndash;2 business days after payment is confirmed. Orders placed on weekends or public holidays will be processed on the next business day. Processing time may be longer during peak seasons or special promotions.</p>\n<h2>Shipping methods &amp; carriers</h2>\n<p>We offer several shipping options through major carriers, including:</p>\n<ul>\n<li><strong>UPS</strong> &mdash; Ground, Expedited, Overnight (where available)</li>\n<li><strong>FedEx</strong> &mdash; Ground, 2-Day, Overnight (where available)</li>\n<li><strong>USPS</strong> &mdash; First-Class, Priority Mail, Priority Mail Express</li>\n<li><strong>Local pickup</strong> &mdash; Choose in-store/local pickup at checkout if available in your area</li>\n</ul>\n<p>Available carriers and services depend on the shipping address, package size, and selected shipping speed at checkout.</p>\n<h2>Shipping rates &amp; delivery estimates</h2>\n<p>Shipping charges are calculated at checkout based on the selected carrier, service level, package weight/dimensions, and destination. Delivery timeframes are estimates and begin from the date the order is shipped (not the date the order is placed).</p>\n<ul>\n<li><strong>Standard (Domestic)</strong>: typically 3&ndash;7 business days</li>\n<li><strong>Expedited</strong>: typically 2&ndash;3 business days</li>\n<li><strong>Overnight</strong>: typically 1 business day (subject to carrier availability and cutoff times)</li>\n<li><strong>International</strong>: varies widely by country and customs processing; allow additional time</li>\n</ul>\n<h2>Tracking</h2>\n<p>Once your order ships, a confirmation email with tracking information will be sent to the email address provided at checkout. Tracking updates may take up to 24 hours to appear on the carrier&rsquo;s website after shipment.</p>\n<h2>Local pickup</h2>\n<ul>\n<li>Select the \"Local pickup\" option at checkout if available for your area.</li>\n<li>You will receive a notification when your order is ready for pickup. Please bring a valid photo ID and your order confirmation or pickup code.</li>\n<li>Pickup hours and location details will be provided in the notification. Orders not collected within a specified hold period (typically 7&ndash;14 days) may be cancelled or returned to inventory.</li>\n</ul>\n<h2>Address changes &amp; cancellations</h2>\n<p>If you need to change your shipping address or cancel an order, contact customer support as soon as possible. We may be able to modify or cancel orders that have not yet shipped. Once an order has shipped, changes may not be possible and additional fees may apply for rerouting or returns.</p>\n<h2>Lost, damaged, or delayed shipments</h2>\n<p>If your package is lost, damaged, or delayed, please:</p>\n<ol>\n<li>Check the tracking information for the latest updates.</li>\n<li>Inspect the package and keep all packaging and documentation if items are damaged.</li>\n<li>Contact customer support with your order number and photos (if applicable) so we can assist and work with the carrier.</li>\n</ol>\n<h2>Customs, duties &amp; taxes (International orders)</h2>\n<p>For international shipments, recipients are responsible for any customs duties, taxes, or import fees imposed by the destination country. These fees are not included in the item price or shipping cost and may result in delivery delays.</p>\n<h2>Shipping exceptions &amp; delays</h2>\n<p>Occasional delays may occur due to carrier backlogs, severe weather, natural disasters, customs processing, or other factors beyond our control. We appreciate your patience in such situations and will provide updates when information is available.</p>\n<h2>Contact</h2>\n<p>If you have questions about shipping, tracking, or local pickup, please contact our customer support team via the website contact form or the support channel provided at checkout. Provide your order number for faster assistance.</p>\n</div>', 'Shipping Policy', '', 'Shipping Policy shipping policy Shipping Policy This shipping policy explains how orders are processed and shipped, the carriers we use, delivery estimates, and options for local pickup. Shipping practices and timelines may vary by carrier, product, and destination. Order processing Most orders are processed within 1&ndash;2 business days after payment is confirmed. Orders placed on weekends or public holidays will be processed on the next business day. Processing time may be longer during peak seasons or special promotions. Shipping methods &amp; carriers We offer several shipping options through major carriers, including: UPS &mdash; Ground, Expedited, Overnight (where available) FedEx &mdash; Ground, 2-Day, Overnight (where available) USPS &mdash; First-Class, Priority Mail, Priority Mail Express Local pickup &mdash; Choose in-store/local pickup at checkout if available in your area Available carriers and services depend on the shipping address, package size, and selected shipping speed at checkout. Shipping rates &amp; delivery estimates Shipping charges are calculated at checkout based on the selected carrier, service level, package weight/dimensions, and destination. Delivery timeframes are estimates and begin from the date the order is shipped (not the date the order is placed). Standard (Domestic): typically 3&ndash;7 business days Expedited: typically 2&ndash;3 business days Overnight: typically 1 business day (subject to carrier availability and cutoff times) International: varies widely by country and customs processing; allow additional time Tracking Once your order ships, a confirmation email with tracking information will be sent to the email address provided at checkout. Tracking updates may take up to 24 hours to appear on the carrier&rsquo;s website after shipment. Local pickup Select the \"Local pickup\" option at checkout if available for your area. You will receive a notification when your order is ready for pickup. Please bring a valid photo ID and your order confirmation or pickup code. Pickup hours and location details will be provided in the notification. Orders not collected within a specified hold period (typically 7&ndash;14 days) may be cancelled or returned to inventory. Address changes &amp; cancellations If you need to change your shipping address or cancel an order, contact customer support as soon as possible. We may be able to modify or cancel orders that have not yet shipped. Once an order has shipped, changes may not be possible and additional fees may apply for rerouting or returns. Lost, damaged, or delayed shipments If your package is lost, damaged, or delayed, please: Check the tracking information for the latest updates. Inspect the package and keep all packaging and documentation if items are damaged. Contact customer support with your order number and photos (if applicable) so we can assist and work with the carrier. Customs, duties &amp; taxes (International orders) For international shipments, recipients are responsible for any customs duties, taxes, or import fees imposed by the destination country. These fees are not included in the item price or shipping cost and may result in delivery delays. Shipping exceptions &amp; delays Occasional delays may occur due to carrier backlogs, severe weather, natural disasters, customs processing, or other factors beyond our control. We appreciate your patience in such situations and will provide updates when information is available. Contact If you have questions about shipping, tracking, or local pickup, please contact our customer support team via the website contact form or the support channel provided at checkout. Provide your order number for faster assistance.', 0, NULL, NULL, 0, NULL, NULL, '', '', NULL, NULL, NULL, NULL, 'local', 0, NULL, NULL, NULL, NULL, NULL, NULL, 'middle-center', NULL, NULL, '320px', 1, 0, 1, 0, 1, 0, 1, '', '', NULL, 1, 1, 1, NULL, 0, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-05 21:54:27', '2026-08-05 21:55:18');
INSERT INTO `cms_pages` VALUES (21, 'Featured Items', 'featured-items', '<div class=\"prose prose-slate max-w-none\" style=\"max-width: none !important; width: 100%;\">\n<h1 style=\"text-align: center;\">Check Out These Recommended Items!</h1>\n<p style=\"text-align: center;\">[plugin:featured-items display=list]</p>\n<p style=\"text-align: center;\">&nbsp;</p>\n</div>', 'Featured Items', '', 'Featured Items featured items Featured Items Check Out These Recommended Items! &nbsp;', 0, NULL, NULL, 0, NULL, NULL, '', '', NULL, NULL, NULL, NULL, 'local', 0, NULL, NULL, NULL, NULL, NULL, NULL, 'middle-center', NULL, NULL, '320px', 1, 0, 1, 0, 1, 0, 1, '', '', NULL, 0, 0, 0, NULL, 0, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-06 00:27:44', '2026-08-06 00:31:12');
INSERT INTO `cms_pages` VALUES (22, 'Refunds, Returns & Exchanges', 'returns-refunds-policy', '<div class=\"prose prose-slate max-w-none\" style=\"max-width: none !important; width: 100%;\">\n<h1>Refunds &amp; Returns Policy</h1>\n<p>We want you to be satisfied with every purchase. This policy explains how returns, exchanges, and refunds are handled for physical products, digital products, and event tickets. It is written to be general and applies to orders unless otherwise noted at checkout or in a specific product listing.</p>\n<h2>Quick summary</h2>\n<ul>\n<li>Physical items: Returns accepted within 30 days if in original condition (unless otherwise stated).</li>\n<li>Digital items: Generally non-refundable; defects or material misrepresentation will be reviewed case-by-case.</li>\n<li>Events/tickets: Refund and cancellation rules vary by event; see details below.</li>\n<li>To start any return or refund request, contact support with your order number and details.</li>\n</ul>\n<h2>Physical (shippable) items</h2>\n<p>Eligibility and condition:</p>\n<ul>\n<li>Returns are accepted within 30 days of delivery for most items unless a product page states otherwise.</li>\n<li>Items must be returned in unused condition, with original packaging, accessories, and proof of purchase.</li>\n<li>Personalized or custom-made items, perishable goods, and certain health or hygiene products are final sale and cannot be returned unless defective.</li>\n</ul>\n<p>Return process:</p>\n<ol>\n<li>Contact support (see Contact section) with your order number, item(s), reason for return, and photos if applicable.</li>\n<li>If your return is approved, you will receive return instructions and an RMA (Return Merchandise Authorization) number when required.</li>\n<li>Ship the item using a trackable shipping method and retain tracking information until the return is complete.</li>\n</ol>\n<p>Refunds and shipping costs:</p>\n<ul>\n<li>Refunds are issued to the original payment method once the return has been inspected.</li>\n<li>Processing and inspection typically take up to 5&ndash;10 business days after we receive the returned item.</li>\n<li>Original shipping charges are non-refundable except when the return is a result of our error (e.g., wrong or defective item).</li>\n<li>Return shipping costs are the responsibility of the customer unless otherwise stated. In cases of our error, we will cover return shipping.</li>\n<li>Some returns may be subject to a restocking fee if the item is not returned in original condition.</li>\n</ul>\n<h2>Damaged or incorrect items</h2>\n<p>If you receive a damaged or incorrect item, please contact us immediately. For fastest resolution include:</p>\n<ul>\n<li>Order number</li>\n<li>Photos showing the damage or the incorrect item received</li>\n<li>A brief description of the issue</li>\n</ul>\n<p>We will review the claim and, if approved, provide a prepaid return label, send a replacement, or issue a refund based on your preference and product availability. Report shipping damage or incorrect items within 7 days of delivery to ensure prompt handling.</p>\n<h2>Digital products (downloads, software, online content)</h2>\n<p>Digital products are delivered instantly or via download and, as such, are generally non-refundable once delivered or accessed. However, we will consider refund requests in the following circumstances:</p>\n<ul>\n<li>The product is defective or materially not as described.</li>\n<li>There was a purchaser error in the product listing (rare).</li>\n</ul>\n<p>To request a review, contact support with your order number, a description of the problem, and any relevant screenshots or files. Approved refunds for digital goods are issued at our discretion and are typically processed within 5&ndash;10 business days.</p>\n<h2>Event tickets and registrations</h2>\n<p>Ticket and event refund policies vary by event. Unless otherwise stated at the time of purchase:</p>\n<ul>\n<li>Refunds are available up to 14 days before the event start date, minus any applicable processing fees.</li>\n<li>Tickets are non-refundable within 14 days of the event, except when the event is canceled by the organizer.</li>\n<li>If an event is postponed or rescheduled, tickets will typically remain valid for the new date. If you cannot attend the rescheduled date, follow the refund instructions provided for that event.</li>\n<li>Transfers or name changes may be permitted for certain events&mdash;contact support for assistance.</li>\n</ul>\n<p>If an event is canceled by the organizer, you will be notified with instructions for refunds or credit options. Processing time for ticket refunds is typically 5&ndash;15 business days after cancellation is confirmed.</p>\n<h2>Exchanges</h2>\n<p>Exchanges for different sizes or colors are handled like returns: contact support to request an exchange, return the original item following the provided instructions, and once received and inspected, we will ship the replacement. Customers are responsible for return shipping unless the exchange is due to our error.</p>\n<h2>How to request a return or refund</h2>\n<ol>\n<li>Email support@example.com with the subject line &ldquo;Return/Refund Request: Order #XXXX&rdquo;.</li>\n<li>Include your full name, order number, items involved, reason for return/refund, and photos if applicable.</li>\n<li>Allow 48&ndash;72 business hours for an initial response. We will provide next steps, an RMA if applicable, and shipping instructions.</li>\n</ol>\n<h2>Processing times and refunds posting</h2>\n<ul>\n<li>We aim to process approved refunds within 5&ndash;10 business days after receiving and inspecting returns.</li>\n<li>Once processed, it may take an additional 3&ndash;10 business days for the refund to appear on your bank or card statement, depending on your payment provider.</li>\n</ul>\n<aside><strong>Note:</strong> If you paid with a third-party payment service (e.g., PayPal, Apple Pay, etc.), refunds will generally be returned to that same payment method and are subject to the third party&rsquo;s processing times and policies.</aside>\n<h2>Chargebacks</h2>\n<p>If you are considering a chargeback through your bank or card issuer, please contact us first. Chargebacks can delay resolution and may result in the loss of certain protections. We will work with you to resolve any issues directly and fairly.</p>\n<h2>Exceptions &amp; final sale items</h2>\n<p>Certain items are final sale and not eligible for return or refund, including but not limited to:</p>\n<ul>\n<li>Personalized or custom-made items</li>\n<li>Perishable goods</li>\n<li>Gift cards</li>\n<li>Products explicitly labeled &ldquo;Final Sale&rdquo; at the time of purchase</li>\n</ul>\n<h2>Privacy and returned items</h2>\n<p>Any personal information collected during a return or refund request will be handled in accordance with our Privacy Policy and used only to process your request.</p>\n<h2>Contact</h2>\n<p>To initiate a return or request help, contact our Support team:</p>\n<ul>\n<li>Email: support@example.com</li>\n<li>Response time: Typically within 48&ndash;72 business hours</li>\n</ul>\n<p>This policy may be updated periodically. Please review this page for the most current information.</p>\n</div>', 'Returns & Refunds Policy', '', 'Refunds, Returns & Exchanges returns refunds policy Returns & Refunds Policy Refunds &amp; Returns Policy We want you to be satisfied with every purchase. This policy explains how returns, exchanges, and refunds are handled for physical products, digital products, and event tickets. It is written to be general and applies to orders unless otherwise noted at checkout or in a specific product listing. Quick summary Physical items: Returns accepted within 30 days if in original condition (unless otherwise stated). Digital items: Generally non-refundable; defects or material misrepresentation will be reviewed case-by-case. Events/tickets: Refund and cancellation rules vary by event; see details below. To start any return or refund request, contact support with your order number and details. Physical (shippable) items Eligibility and condition: Returns are accepted within 30 days of delivery for most items unless a product page states otherwise. Items must be returned in unused condition, with original packaging, accessories, and proof of purchase. Personalized or custom-made items, perishable goods, and certain health or hygiene products are final sale and cannot be returned unless defective. Return process: Contact support (see Contact section) with your order number, item(s), reason for return, and photos if applicable. If your return is approved, you will receive return instructions and an RMA (Return Merchandise Authorization) number when required. Ship the item using a trackable shipping method and retain tracking information until the return is complete. Refunds and shipping costs: Refunds are issued to the original payment method once the return has been inspected. Processing and inspection typically take up to 5&ndash;10 business days after we receive the returned item. Original shipping charges are non-refundable except when the return is a result of our error (e.g., wrong or defective item). Return shipping costs are the responsibility of the customer unless otherwise stated. In cases of our error, we will cover return shipping. Some returns may be subject to a restocking fee if the item is not returned in original condition. Damaged or incorrect items If you receive a damaged or incorrect item, please contact us immediately. For fastest resolution include: Order number Photos showing the damage or the incorrect item received A brief description of the issue We will review the claim and, if approved, provide a prepaid return label, send a replacement, or issue a refund based on your preference and product availability. Report shipping damage or incorrect items within 7 days of delivery to ensure prompt handling. Digital products (downloads, software, online content) Digital products are delivered instantly or via download and, as such, are generally non-refundable once delivered or accessed. However, we will consider refund requests in the following circumstances: The product is defective or materially not as described. There was a purchaser error in the product listing (rare). To request a review, contact support with your order number, a description of the problem, and any relevant screenshots or files. Approved refunds for digital goods are issued at our discretion and are typically processed within 5&ndash;10 business days. Event tickets and registrations Ticket and event refund policies vary by event. Unless otherwise stated at the time of purchase: Refunds are available up to 14 days before the event start date, minus any applicable processing fees. Tickets are non-refundable within 14 days of the event, except when the event is canceled by the organizer. If an event is postponed or rescheduled, tickets will typically remain valid for the new date. If you cannot attend the rescheduled date, follow the refund instructions provided for that event. Transfers or name changes may be permitted for certain events&mdash;contact support for assistance. If an event is canceled by the organizer, you will be notified with instructions for refunds or credit options. Processing time for ticket refunds is typically 5&ndash;15 business days after cancellation is confirmed. Exchanges Exchanges for different sizes or colors are handled like returns: contact support to request an exchange, return the original item following the provided instructions, and once received and inspected, we will ship the replacement. Customers are responsible for return shipping unless the exchange is due to our error. How to request a return or refund Email support@example.com with the subject line &ldquo;Return/Refund Request: Order #XXXX&rdquo;. Include your full name, order number, items involved, reason for return/refund, and photos if applicable. Allow 48&ndash;72 business hours for an initial response. We will provide next steps, an RMA if applicable, and shipping instructions. Processing times and refunds posting We aim to process approved refunds within 5&ndash;10 business days after receiving and inspecting returns. Once processed, it may take an additional 3&ndash;10 business days for the refund to appear on your bank or card statement, depending on your payment provider. Note: If you paid with a third-party payment service (e.g., PayPal, Apple Pay, etc.), refunds will generally be returned to that same payment method and are subject to the third party&rsquo;s processing times and policies. Chargebacks If you are considering a chargeback through your bank or card issuer, please contact us first. Chargebacks can delay resolution and may result in the loss of certain protections. We will work with you to resolve any issues directly and fairly. Exceptions &amp; final sale items Certain items are final sale and not eligible for return or refund, including but not limited to: Personalized or custom-made items Perishable goods Gift cards Products explicitly labeled &ldquo;Final Sale&rdquo; at the time of purchase Privacy and returned items Any personal information collected during a return or refund request will be handled in accordance with our Privacy Policy and used only to process your request. Contact To initiate a return or request help, contact our Support team: Email: support@example.com Response time: Typically within 48&ndash;72 business hours This policy may be updated periodically. Please review this page for the most current information.', 0, NULL, NULL, 0, NULL, NULL, '', '', NULL, NULL, NULL, NULL, 'local', 0, NULL, NULL, NULL, NULL, NULL, NULL, 'middle-center', NULL, NULL, '320px', 1, 0, 1, 0, 1, 0, 1, '', '', NULL, 1, 1, 1, NULL, 0, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-06 00:58:32', '2026-08-06 00:58:32');
INSERT INTO `cms_pages` VALUES (23, 'Brands', 'brands', '<div class=\"prose prose-slate max-w-none\" style=\"max-width: none !important; width: 100%;\">\n<h1 style=\"text-align: center;\">Our Brands</h1>\n<p>&nbsp;</p>\n</div>\n<p>[plugin:brands-2026 display=grid show_label=1]</p>\n<p>&nbsp;</p>', 'Our Brands', '', 'Brands brands Our Brands Our Brands &nbsp; &nbsp;', 0, NULL, NULL, 0, NULL, NULL, '', '', NULL, NULL, NULL, NULL, 'local', 0, NULL, NULL, NULL, NULL, NULL, NULL, 'middle-center', NULL, NULL, '320px', 1, 0, 1, 0, 1, 0, 1, '', '', NULL, 0, 0, 0, NULL, 0, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-06 02:46:51', '2026-08-06 02:48:52');
INSERT INTO `cms_pages` VALUES (24, 'Testimonials', 'testimonials', '<div class=\"prose prose-slate max-w-none\" style=\"max-width: none !important; width: 100%;\">\n<p style=\"text-align: center;\">&nbsp;</p>\n</div>\n<p style=\"text-align: center;\">[plugin:testimonials-2026 display=list]</p>\n<p style=\"text-align: center;\">&nbsp;</p>', 'Client Testimonials', '', 'Testimonials testimonials Client Testimonials &nbsp; &nbsp;', 0, NULL, NULL, 0, NULL, NULL, '', '', NULL, NULL, NULL, NULL, 'local', 0, NULL, NULL, NULL, NULL, NULL, NULL, 'middle-center', NULL, NULL, '320px', 1, 0, 1, 0, 1, 0, 1, '', '', NULL, 0, 1, 0, NULL, 0, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-09 23:34:27', '2026-08-09 23:36:25');
