INSERT INTO `cms_testimonials` VALUES (1, 'Joan F.', 'Verified Buyer', 'This is a great shopping website! I\'ve ordered twice in the past and will order again in the future. Great price, great items, great customer service!', 'https://images.unsplash.com/photo-1494790108377-be9c29b29330?w=150&auto=format&fit=crop&q=80', 5, 'Fashion Weekly', NULL, 1, 1, '2026-07-22 12:49:40', '2026-07-26 22:52:19');
INSERT INTO `cms_testimonials` VALUES (2, 'Mike P.', 'Regular Customer', 'Always has the best prices and fastest shipping. I highly recommend this company and will continue to use them for future orders.', 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?w=150&auto=format&fit=crop&q=80', 5, 'Apex Studios', NULL, 1, 2, '2026-07-22 12:49:40', '2026-07-22 12:49:40');
INSERT INTO `cms_testimonials` VALUES (3, 'Terry Fisk', 'Business Owner', 'This is a great store website. They always have what I need for corporate gifts and seasonal promotions.', 'https://images.unsplash.com/photo-1500648767791-00dcc994a43e?w=150&auto=format&fit=crop&q=80', 5, 'Aspire Properties', 'https://example.com', 1, 3, '2026-07-22 12:49:40', '2026-07-22 12:49:40');
INSERT INTO `cms_testimonials` VALUES (4, 'Matt Jones', 'Product Reviewer', 'An outstanding e-commerce platform offering top quality items with flawless customer support.', 'https://images.unsplash.com/photo-1534528741775-53994a69daeb?w=150&auto=format&fit=crop&q=80', 5, 'Tech Pulse', NULL, 1, 4, '2026-07-22 12:49:40', '2026-07-22 12:49:40');
