INSERT INTO `email_template_translations` VALUES (1, 1, 2, 'Confirmación de Pedido # {{order_id}}', NULL, 'Estimado/a {{customer_name}},', '<p><strong>¡Agradecemos su pedido!</strong></p><p>Si necesita asistencia, por favor envíe un ticket de soporte o mándenos un correo electrónico.</p>', '<p>A continuación se detallan los datos de su pedido.</p>', 'Atentamente,', 'Departamento de Ventas', 'Si tiene alguna pregunta sobre este pedido, ¡no dude en contactarnos en cualquier momento!', 'Copyright 2026', NULL, 'ai_translated', '2026-08-10 16:27:14', '2026-07-29 12:54:58', '2026-08-10 16:27:19');
INSERT INTO `email_template_translations` VALUES (2, 2, 2, 'Confirmación de Envío de Pedido en Línea # {{order_id}}', NULL, 'Estimado/a {{customer_name}},', '<p>Este es un mensaje de notificación de envío. ¡Su pedido ha sido enviado!</p>', '<p>Número de seguimiento: {{tracking_number}}</p><p>{{order_items_table}}</p>', 'Atentamente,', 'Departamento de Ventas', 'Si tiene alguna pregunta sobre su pedido, no dude en ponerse en contacto con nosotros.', 'Copyright 2026', NULL, 'ai_translated', '2026-08-10 16:27:19', '2026-07-29 12:55:04', '2026-08-10 16:27:24');
INSERT INTO `email_template_translations` VALUES (3, 3, 2, 'Recordatorio de descarga -- ID de pedido # {{order_id}}', NULL, 'Estimado/a {{customer_name}},', '<p><strong>Solo queríamos recordarte que descargues tu(s) producto(s) que ordenaste recientemente.</strong></p>', '<p>Puedes acceder a tu(s) enlace(s) de descarga a continuación:</p><p>{{download_links}}</p><p>{{order_items_table}}</p>', 'Atentamente,', 'Equipo de Soporte al Cliente', 'Las descargas expiran en 7 días.', 'Copyright 2026', NULL, 'ai_translated', '2026-08-10 16:27:24', '2026-07-29 12:55:12', '2026-08-10 16:27:30');
INSERT INTO `email_template_translations` VALUES (4, 4, 2, 'Confirmación de Registro de Cuenta', NULL, 'Estimado/a {{customer_name}},', '<p>¡Gracias por registrarte para una cuenta en línea!</p>', '<p>Esperamos poder brindarle un excelente servicio.</p>', 'Atentamente,', 'Departamento de Ventas', 'Si tiene alguna pregunta sobre su cuenta, no dude en ponerse en contacto con nosotros.', 'Copyright 2026', NULL, 'ai_translated', '2026-08-10 16:27:30', '2026-07-29 12:55:17', '2026-08-10 16:27:38');
INSERT INTO `email_template_translations` VALUES (5, 5, 2, 'Registro de Cuenta Mayorista', NULL, 'Estimado/a {{customer_name}},', '<p>¡Gracias por registrarte para una cuenta mayorista en línea!</p>', '<p>Esperamos poder brindarle un excelente servicio. Nuestros administradores revisarán sus credenciales de mayorista en breve.</p>', 'Atentamente,', 'Departamento de Ventas', 'Si tiene alguna pregunta sobre su cuenta, no dude en ponerse en contacto con nosotros.', 'Copyright 2026', NULL, 'ai_translated', '2026-08-10 16:27:38', '2026-07-29 12:55:23', '2026-08-10 16:27:43');
INSERT INTO `email_template_translations` VALUES (6, 6, 2, 'Se requiere activación de cuenta', NULL, 'Estimado/a {{customer_name}},', '<p>Gracias por registrarte para una cuenta en nuestro sitio web.</p>', '<p>Para completar el proceso de registro, debes hacer clic en el enlace de abajo para activar tu cuenta:</p><p><a href=\"{{activation_url}}\" style=\"background-color: #4f46e5; color: #ffffff; padding: 10px 20px; text-decoration: none; border-radius: 6px; display: inline-block;\">Activar Cuenta</a></p>', 'Atentamente,', 'Departamento de Soporte al Cliente.', 'Si tiene alguna pregunta sobre su cuenta, no dude en ponerse en contacto con nosotros.', 'Copyright 2026', NULL, 'ai_translated', '2026-08-10 16:27:43', '2026-07-29 12:55:30', '2026-08-10 16:27:49');
INSERT INTO `email_template_translations` VALUES (7, 7, 2, 'Solicitud de Restablecimiento de Contraseña', NULL, 'Estimado/a {{customer_name}},', '<p>Está recibiendo este correo electrónico porque hemos recibido una solicitud de restablecimiento de contraseña para su cuenta.</p>', '<p>Por favor, haga clic en el botón de abajo para restablecer su contraseña:</p><p><a href=\"{{reset_url}}\" style=\"background-color: #4f46e5; color: #ffffff; padding: 10px 20px; text-decoration: none; border-radius: 6px; display: inline-block;\">Restablecer Contraseña</a></p><p>Este enlace para restablecer la contraseña expirará en 60 minutos.</p><p>Si no solicitó un restablecimiento de contraseña, no se requiere ninguna acción adicional.</p>', 'Atentamente,', 'Departamento de Soporte al Cliente.', 'Si tiene problemas para hacer clic en el botón de restablecimiento, copie y pegue la URL en su navegador web.', 'Copyright 2026', NULL, 'ai_translated', '2026-08-10 16:27:49', '2026-07-29 12:55:38', '2026-08-10 16:27:55');
INSERT INTO `email_template_translations` VALUES (8, 8, 2, 'Ticket de Soporte Enviado: {{ticket_title}}', NULL, 'Hola {{customer_name}},', '<p>Gracias por contactar con soporte. Hemos recibido su ticket <strong>\"{{ticket_title}}\"</strong> y nuestro equipo lo revisará en breve.</p>', '<p><strong>Estado actual:</strong> {{ticket_status}}</p><p><a href=\"{{ticket_url}}\" style=\"background-color: #4f46e5; color: #ffffff; padding: 10px 20px; text-decoration: none; border-radius: 6px; display: inline-block;\">Ver su ticket</a></p>', 'Gracias,', 'Equipo de Soporte al Cliente', 'Puede responder directamente a este correo electrónico para agregar actualizaciones a su ticket.', 'Copyright 2026. Todos los derechos reservados.', NULL, 'ai_translated', '2026-08-10 16:27:55', '2026-07-29 12:55:45', '2026-08-10 16:28:00');
INSERT INTO `email_template_translations` VALUES (9, 9, 2, 'Nueva respuesta en el ticket: {{ticket_title}}', NULL, 'Hola {{customer_name}},', '<p>Hay una nueva respuesta en tu ticket <strong>\"{{ticket_title}}\"</strong> de {{reply_author}}.</p>', '<div style=\"border-left: 4px solid #e2e8f0; padding-left: 16px; margin: 16px 0; color: #475569;\">{{reply_body}}</div><p><a href=\"{{ticket_url}}\" style=\"background-color: #4f46e5; color: #ffffff; padding: 10px 20px; text-decoration: none; border-radius: 6px; display: inline-block;\">Ver Conversación</a></p>', 'Gracias,', 'Equipo de Soporte al Cliente', 'Puedes responder directamente a este correo electrónico para continuar la conversación.', 'Copyright 2026. Todos los derechos reservados.', NULL, 'ai_translated', '2026-08-10 16:28:00', '2026-07-29 12:55:51', '2026-08-10 16:28:07');
INSERT INTO `email_template_translations` VALUES (10, 10, 2, 'Actualización de Ticket: {{ticket_title}} ahora está {{ticket_status}}', NULL, 'Hola {{customer_name}},', '<p>Su ticket de soporte <strong>\"{{ticket_title}}\"</strong> ha sido actualizado.</p>', '<p><strong>Estado anterior:</strong> {{previous_status}}</p><p><strong>Nuevo estado:</strong> {{ticket_status}}</p><p><a href=\"{{ticket_url}}\" style=\"background-color: #4f46e5; color: #ffffff; padding: 10px 20px; text-decoration: none; border-radius: 6px; display: inline-block;\">Ver su ticket</a></p>', 'Gracias,', 'Equipo de Soporte al Cliente', 'Puedes responder directamente a este correo electrónico para agregar actualizaciones a tu ticket.', 'Copyright 2026. Todos los derechos reservados.', NULL, 'ai_translated', '2026-08-10 16:28:07', '2026-07-29 12:55:59', '2026-08-10 16:28:12');
INSERT INTO `email_template_translations` VALUES (11, 1, 3, 'Confirmation de commande # {{order_id}}', NULL, 'Cher {{customer_name}},', '<p><strong>Nous apprécions votre commande !</strong></p><p>Si vous avez besoin d\'aide, veuillez soumettre un ticket de support ou nous envoyer un e-mail.</p>', '<p>Voici les détails de votre commande.</p>', 'Cordialement,', 'Département des Ventes', 'Si vous avez des questions concernant cette commande, n\'hésitez pas à nous contacter à tout moment !', 'Droit d\'auteur 2026', NULL, 'ai_translated', '2026-08-10 17:22:59', '2026-08-04 17:15:16', '2026-08-10 17:23:07');
INSERT INTO `email_template_translations` VALUES (12, 2, 3, 'Confirmation d\'expédition de commande en ligne # {{order_id}}', NULL, 'Cher {{customer_name}},', '<p>Ceci est un message de notification d\'expédition. Votre commande a été expédiée !</p>', '<p>Numéro de suivi : {{tracking_number}}</p><p>{{order_items_table}}</p>', 'Cordialement,', 'Département des ventes', 'Si vous avez des questions concernant votre commande, n\'hésitez pas à nous contacter.', 'Droit d\'auteur 2026', NULL, 'ai_translated', '2026-08-10 17:23:07', '2026-08-04 17:15:21', '2026-08-10 17:23:12');
INSERT INTO `email_template_translations` VALUES (13, 3, 3, 'Rappel de téléchargement -- ID de commande # {{order_id}}', NULL, 'Cher {{customer_name}},', '<p><strong>Nous voulions juste vous rappeler de télécharger votre(vos) produit(s) que vous avez récemment commandé(s).</strong></p>', '<p>Vous pouvez accéder à votre(s) lien(s) de téléchargement ci-dessous :</p><p>{{download_links}}</p><p>{{order_items_table}}</p>', 'Cordialement,', 'Équipe de support client', 'Les téléchargements expirent dans 7 jours.', 'Droit d\'auteur 2026', NULL, 'ai_translated', '2026-08-10 17:23:12', '2026-08-04 17:15:27', '2026-08-10 17:23:17');
INSERT INTO `email_template_translations` VALUES (14, 4, 3, 'Confirmation d\'inscription au compte', NULL, 'Cher {{customer_name}},', '<p>Merci de vous être inscrit pour un compte en ligne !</p>', '<p>Nous sommes impatients de vous offrir un excellent service.</p>', 'Cordialement,', 'Département des ventes', 'Si vous avez des questions concernant votre compte, n\'hésitez pas à nous contacter.', 'Droit d\'auteur 2026', NULL, 'ai_translated', '2026-08-10 17:23:17', '2026-08-04 17:15:33', '2026-08-10 17:23:22');
INSERT INTO `email_template_translations` VALUES (15, 5, 3, 'Inscription au compte de gros', NULL, 'Cher {{customer_name}},', '<p>Merci de vous être inscrit pour un compte de gros en ligne !</p>', '<p>Nous sommes impatients de vous fournir un excellent service. Nos administrateurs examineront vos informations d\'identification de gros sous peu.</p>', 'Cordialement,', 'Département des Ventes', 'Si vous avez des questions concernant votre compte, n\'hésitez pas à nous contacter.', 'Droit d\'auteur 2026', NULL, 'ai_translated', '2026-08-10 17:23:22', '2026-08-04 17:15:38', '2026-08-10 17:23:27');
INSERT INTO `email_template_translations` VALUES (16, 6, 3, 'Activation de compte requise', NULL, 'Cher {{customer_name}},', '<p>Merci de vous être inscrit pour un compte sur notre site web.</p>', '<p>Pour compléter le processus d\'inscription, vous devez cliquer sur le lien ci-dessous pour activer votre compte :</p><p><a href=\"{{activation_url}}\" style=\"background-color: #4f46e5; color: #ffffff; padding: 10px 20px; text-decoration: none; border-radius: 6px; display: inline-block;\">Activer le compte</a></p>', 'Cordialement,', 'Département du support client.', 'Si vous avez des questions concernant votre compte, n\'hésitez pas à nous contacter.', 'Droit d\'auteur 2026', NULL, 'ai_translated', '2026-08-10 17:23:27', '2026-08-04 17:15:44', '2026-08-10 17:23:33');
INSERT INTO `email_template_translations` VALUES (17, 7, 3, 'Demande de réinitialisation de mot de passe', NULL, 'Cher {{customer_name}},', '<p>Vous recevez cet e-mail car nous avons reçu une demande de réinitialisation de mot de passe pour votre compte.</p>', '<p>Veuillez cliquer sur le bouton ci-dessous pour réinitialiser votre mot de passe :</p><p><a href=\"{{reset_url}}\" style=\"background-color: #4f46e5; color: #ffffff; padding: 10px 20px; text-decoration: none; border-radius: 6px; display: inline-block;\">Réinitialiser le mot de passe</a></p><p>Ce lien de réinitialisation de mot de passe expirera dans 60 minutes.</p><p>Si vous n\'avez pas demandé de réinitialisation de mot de passe, aucune autre action n\'est requise.</p>', 'Cordialement,', 'Département de support client.', 'Si vous avez des difficultés à cliquer sur le bouton de réinitialisation, copiez et collez l\'URL dans votre navigateur web.', 'Droits d\'auteur 2026', NULL, 'ai_translated', '2026-08-10 17:23:33', '2026-08-04 17:15:50', '2026-08-10 17:23:39');
INSERT INTO `email_template_translations` VALUES (18, 8, 3, 'Ticket de support soumis : {{ticket_title}}', NULL, 'Bonjour {{customer_name}},', '<p>Merci de contacter le support. Nous avons reçu votre ticket <strong>\"{{ticket_title}}\"</strong> et notre équipe l\'examinera sous peu.</p>', '<p><strong>État actuel :</strong> {{ticket_status}}</p><p><a href=\"{{ticket_url}}\" style=\"background-color: #4f46e5; color: #ffffff; padding: 10px 20px; text-decoration: none; border-radius: 6px; display: inline-block;\">Voir votre billet</a></p>', 'Merci,', 'Équipe de support client', 'Vous pouvez répondre directement à cet e-mail pour ajouter des mises à jour à votre ticket.', 'Droits d\'auteur 2026. Tous droits réservés.', NULL, 'ai_translated', '2026-08-10 17:23:39', '2026-08-04 17:15:57', '2026-08-10 17:23:45');
INSERT INTO `email_template_translations` VALUES (19, 9, 3, 'Nouvelle réponse sur le ticket : {{ticket_title}}', NULL, 'Bonjour {{customer_name}},', '<p>Il y a une nouvelle réponse à votre ticket <strong>\"{{ticket_title}}\"</strong> de {{reply_author}}.</p>', '<div style=\"border-left: 4px solid #e2e8f0; padding-left: 16px; margin: 16px 0; color: #475569;\">{{reply_body}}</div><p><a href=\"{{ticket_url}}\" style=\"background-color: #4f46e5; color: #ffffff; padding: 10px 20px; text-decoration: none; border-radius: 6px; display: inline-block;\">Voir la conversation</a></p>', 'Merci,', 'Équipe de support client', 'Vous pouvez répondre directement à cet e-mail pour continuer la conversation.', 'Droit d\'auteur 2026. Tous droits réservés.', NULL, 'ai_translated', '2026-08-10 17:23:45', '2026-08-04 17:16:04', '2026-08-10 17:23:50');
INSERT INTO `email_template_translations` VALUES (20, 10, 3, 'Mise à jour du ticket : {{ticket_title}} est maintenant {{ticket_status}}', NULL, 'Bonjour {{customer_name}},', '<p>Votre ticket de support <strong>\"{{ticket_title}}\"</strong> a été mis à jour.</p>', '<p><strong>Statut précédent :</strong> {{previous_status}}</p><p><strong>Nouveau statut :</strong> {{ticket_status}}</p><p><a href=\"{{ticket_url}}\" style=\"background-color: #4f46e5; color: #ffffff; padding: 10px 20px; text-decoration: none; border-radius: 6px; display: inline-block;\">Voir votre ticket</a></p>', 'Merci,', 'Équipe de support client', 'Vous pouvez répondre directement à cet e-mail pour ajouter des mises à jour à votre ticket.', 'Droit d\'auteur 2026. Tous droits réservés.', NULL, 'ai_translated', '2026-08-10 17:23:50', '2026-08-04 17:16:11', '2026-08-10 17:23:55');
INSERT INTO `email_template_translations` VALUES (21, 11, 2, '¿Dejaste algo atrás? ¡Regresa a tu carrito!', NULL, 'Estimado/a {{customer_name}},', '<p><strong>¡Dejaste algunos artículos geniales en tu carrito de compras!</strong></p><p>Guardamos tu carrito para que puedas completar tu compra fácilmente cuando estés listo.</p>', '<p>A continuación se encuentran los artículos actualmente en su carrito:</p><p>{{cart_items_table}}</p><p><a href=\"{{checkout_url}}\" style=\"display:inline-block; background-color:#4f46e5; color:#ffffff; font-weight:bold; padding:12px 24px; border-radius:8px; text-decoration:none;\">Completa tu compra &rarr;</a></p>', 'Atentamente,', 'Departamento de Ventas', 'Si tiene alguna pregunta o necesita ayuda con su pedido, por favor responda a este correo electrónico.', 'Copyright 2026', NULL, 'ai_translated', '2026-08-10 16:28:12', '2026-08-06 15:18:35', '2026-08-10 16:28:18');
INSERT INTO `email_template_translations` VALUES (22, 12, 2, '¡Tu carrito te está esperando! Echa un vistazo de nuevo', NULL, 'Estimado/a {{customer_name}},', '<p><strong>¡Los artículos en tu carrito aún están disponibles!</strong></p><p>Ha pasado una semana desde que agregaste artículos a tu carrito. ¡Completa tu pedido antes de que se agoten los artículos!</p>', '<p>Aquí está lo que te espera en tu carrito:</p><p>{{cart_items_table}}</p><p><a href=\"{{checkout_url}}\" style=\"display:inline-block; background-color:#4f46e5; color:#ffffff; font-weight:bold; padding:12px 24px; border-radius:8px; text-decoration:none;\">Volver al Carrito &rarr;</a></p>', 'Atentamente,', 'Departamento de Ventas', 'Si tiene alguna pregunta o necesita ayuda con su pedido, por favor responda a este correo electrónico.', 'Copyright 2026', NULL, 'ai_translated', '2026-08-10 16:28:18', '2026-08-06 15:18:43', '2026-08-10 16:28:24');
INSERT INTO `email_template_translations` VALUES (23, 11, 3, 'Avez-vous laissé quelque chose derrière vous ? Retournez à votre panier !', NULL, 'Cher {{customer_name}},', '<p><strong>Vous avez laissé de superbes articles dans votre panier !</strong></p><p>Nous avons enregistré votre panier afin que vous puissiez facilement finaliser votre achat quand vous le souhaitez.</p>', '<p>Voici les articles actuellement dans votre panier :</p><p>{{cart_items_table}}</p><p><a href=\"{{checkout_url}}\" style=\"display:inline-block; background-color:#4f46e5; color:#ffffff; font-weight:bold; padding:12px 24px; border-radius:8px; text-decoration:none;\">Finalisez votre achat &rarr;</a></p>', 'Cordialement,', 'Département des Ventes', 'Si vous avez des questions ou avez besoin d\'aide concernant votre commande, veuillez répondre à cet e-mail.', 'Droit d\'auteur 2026', NULL, 'ai_translated', '2026-08-10 17:23:55', '2026-08-06 16:17:31', '2026-08-10 17:24:00');
INSERT INTO `email_template_translations` VALUES (24, 12, 3, 'Votre panier vous attend ! Jetez un autre coup d\'œil', NULL, 'Cher {{customer_name}},', '<p><strong>Les articles dans votre panier sont toujours disponibles !</strong></p><p>Cela fait une semaine que vous avez ajouté des articles à votre panier. Finalisez votre commande avant que les articles ne s\'épuisent !</p>', '<p>Voici ce qui vous attend dans votre panier :</p><p>{{cart_items_table}}</p><p><a href=\"{{checkout_url}}\" style=\"display:inline-block; background-color:#4f46e5; color:#ffffff; font-weight:bold; padding:12px 24px; border-radius:8px; text-decoration:none;\">Retour au panier &rarr;</a></p>', 'Cordialement,', 'Département des Ventes', 'Si vous avez des questions ou avez besoin d\'aide concernant votre commande, veuillez répondre à cet e-mail.', 'Droit d\'auteur 2026', NULL, 'ai_translated', '2026-08-10 17:24:00', '2026-08-06 16:17:38', '2026-08-10 17:24:06');
