INSERT INTO `email_templates` VALUES (1, 1, 'Default Order Confirmation', 'support@visperity.app', 'Online Store', '', 'Order Confirmation # {{order_id}}', '', '', '', 0, 'Dear {{customer_name}},', 1, '<p><strong>We appreciate your order!</strong></p><p>If you need assistance, please submit a support ticket or send us an email.</p>', '<p>Below are the details of your order.</p>', 'Sincerely,', 'Sales Department', 'If you have any questions about this order, please contact us anytime!', 'Copyright 2026', '', '', 0, '', 1, '2026-07-22 12:49:36', '2026-07-22 12:49:36');
INSERT INTO `email_templates` VALUES (2, 2, 'Default Shipment Confirmation', 'support@visperity.app', 'Online Store', '', 'Online Order Shipment Confirmation # {{order_id}}', '', '', '', 0, 'Dear {{customer_name}},', 1, '<p>This is a shipment notification message. Your order has shipped!</p>', '<p>Tracking Number: {{tracking_number}}</p><p>{{order_items_table}}</p>', 'Sincerely,', 'Sales Department', 'If you have any questions about your order, please do not hesitate to contact us.', 'Copyright 2026', '', '', 0, '', 1, '2026-07-22 12:49:36', '2026-07-22 12:49:36');
INSERT INTO `email_templates` VALUES (3, 3, 'Default Download Reminder', 'support@visperity.app', 'Online Store', '', 'Download Reminder -- Order ID # {{order_id}}', '', '', '', 0, 'Dear {{customer_name}},', 1, '<p><strong>We just wanted to remind you to download your product(s) that you recently ordered.</strong></p>', '<p>You can access your download link(s) below:</p><p>{{download_links}}</p><p>{{order_items_table}}</p>', 'Sincerely,', 'Customer Support Team', 'Downloads expire in 7 days.', 'Copyright 2026', '', '', 0, '', 1, '2026-07-22 12:49:36', '2026-07-22 12:49:36');
INSERT INTO `email_templates` VALUES (4, 4, 'Default Retail Registration', 'support@visperity.app', 'Online Store', '', 'Account Registration Confirmation', '', '', '', 0, 'Dear {{customer_name}},', 1, '<p>Thank you for registering for an online account!</p>', '<p>We look forward to providing you with excellent service.</p>', 'Sincerely,', 'Sales Department', 'If you have any questions about your account, please do not hesitate to contact us.', 'Copyright 2026', '', '', 0, '', 1, '2026-07-22 12:49:36', '2026-07-22 12:49:36');
INSERT INTO `email_templates` VALUES (5, 5, 'Default Wholesale Registration', 'support@visperity.app', 'Online Store', '', 'Wholesale Account Registration', '', '', '', 0, 'Dear {{customer_name}},', 1, '<p>Thank you for registering for an online wholesale account!</p>', '<p>We look forward to providing you with excellent service. Our administrators will review your wholesale credentials shortly.</p>', 'Sincerely,', 'Sales Department', 'If you have any questions about your account, please do not hesitate to contact us.', 'Copyright 2026', '', '', 0, '', 1, '2026-07-22 12:49:36', '2026-07-22 12:49:36');
INSERT INTO `email_templates` VALUES (6, 6, 'Default Account Activation', 'support@visperity.app', 'Online Store', '', 'Account Activation Required', '', '', '', 0, 'Dear {{customer_name}},', 1, '<p>Thank you for registering for an account on our website.</p>', '<p>To complete the registration process you must click the link below to activate your account:</p><p><a href=\"{{activation_url}}\" style=\"background-color: #4f46e5; color: #ffffff; padding: 10px 20px; text-decoration: none; border-radius: 6px; display: inline-block;\">Activate Account</a></p>', 'Sincerely,', 'Customer Support Dept.', 'If you have any questions about your account, please do not hesitate to contact us.', 'Copyright 2026', '', '', 0, '', 1, '2026-07-22 12:49:36', '2026-07-22 12:49:36');
INSERT INTO `email_templates` VALUES (7, 7, 'Default Reset Password Request', 'support@visperity.app', 'Online Store', '', 'Reset Password Request', '', '', '', 0, 'Dear {{customer_name}},', 1, '<p>You are receiving this email because we received a password reset request for your account.</p>', '<p>Please click the button below to reset your password:</p><p><a href=\"{{reset_url}}\" style=\"background-color: #4f46e5; color: #ffffff; padding: 10px 20px; text-decoration: none; border-radius: 6px; display: inline-block;\">Reset Password</a></p><p>This password reset link will expire in 60 minutes.</p><p>If you did not request a password reset, no further action is required.</p>', 'Sincerely,', 'Customer Support Dept.', 'If you are having trouble clicking the reset button, copy and paste the URL into your web browser.', 'Copyright 2026', '', '', 0, '', 1, '2026-07-22 12:49:36', '2026-07-22 12:49:36');
INSERT INTO `email_templates` VALUES (8, 8, 'Default Support Ticket Submitted', 'support@visperity.app', 'Support Team', '', 'Support Ticket Submitted: {{ticket_title}}', '', '', '', 0, 'Hi {{customer_name}},', 1, '<p>Thank you for contacting support. We received your ticket <strong>\"{{ticket_title}}\"</strong> and our team will review it shortly.</p>', '<p><strong>Current status:</strong> {{ticket_status}}</p><p><a href=\"{{ticket_url}}\" style=\"background-color: #4f46e5; color: #ffffff; padding: 10px 20px; text-decoration: none; border-radius: 6px; display: inline-block;\">View Your Ticket</a></p>', 'Thanks,', 'Customer Support Team', 'You can reply directly to this email to add updates to your ticket.', 'Copyright 2026. All rights reserved.', '', '', 0, '', 1, '2026-07-22 12:49:36', '2026-07-22 12:49:36');
INSERT INTO `email_templates` VALUES (9, 9, 'Default Support Ticket Reply', 'support@visperity.app', 'Support Team', '', 'New Reply on Ticket: {{ticket_title}}', '', '', '', 0, 'Hi {{customer_name}},', 1, '<p>There is a new reply on your ticket <strong>\"{{ticket_title}}\"</strong> from {{reply_author}}.</p>', '<div style=\"border-left: 4px solid #e2e8f0; padding-left: 16px; margin: 16px 0; color: #475569;\">{{reply_body}}</div><p><a href=\"{{ticket_url}}\" style=\"background-color: #4f46e5; color: #ffffff; padding: 10px 20px; text-decoration: none; border-radius: 6px; display: inline-block;\">View Conversation</a></p>', 'Thanks,', 'Customer Support Team', 'You can reply directly to this email to continue the conversation.', 'Copyright 2026. All rights reserved.', '', '', 0, '', 1, '2026-07-22 12:49:36', '2026-07-22 12:49:36');
INSERT INTO `email_templates` VALUES (10, 10, 'Default Support Ticket Status Updated', 'support@visperity.app', 'Support Team', '', 'Ticket Update: {{ticket_title}} is now {{ticket_status}}', '', '', '', 0, 'Hi {{customer_name}},', 1, '<p>Your support ticket <strong>\"{{ticket_title}}\"</strong> has been updated.</p>', '<p><strong>Previous status:</strong> {{previous_status}}</p><p><strong>New status:</strong> {{ticket_status}}</p><p><a href=\"{{ticket_url}}\" style=\"background-color: #4f46e5; color: #ffffff; padding: 10px 20px; text-decoration: none; border-radius: 6px; display: inline-block;\">View Your Ticket</a></p>', 'Thanks,', 'Customer Support Team', 'You can reply directly to this email to add updates to your ticket.', 'Copyright 2026. All rights reserved.', '', '', 0, '', 1, '2026-07-22 12:49:36', '2026-07-22 12:49:36');
INSERT INTO `email_templates` VALUES (11, 11, 'Default 24-Hour Abandoned Cart Reminder', 'support@visperity.app', 'Online Store', '', 'Did you leave something behind? Return to your cart!', '', '', '', 0, 'Dear {{customer_name}},', 1, '<p><strong>You left some great items in your shopping cart!</strong></p><p>We saved your cart so you can easily complete your purchase whenever you\'re ready.</p>', '<p>Below are the items currently in your cart:</p><p>{{cart_items_table}}</p><p><a href=\"{{checkout_url}}\" style=\"display:inline-block; background-color:#4f46e5; color:#ffffff; font-weight:bold; padding:12px 24px; border-radius:8px; text-decoration:none;\">Complete Your Purchase &rarr;</a></p>', 'Sincerely,', 'Sales Department', 'If you have any questions or need help with your order, please reply to this email.', 'Copyright 2026', '', '', 0, '', 1, '2026-08-06 03:34:11', '2026-08-06 03:34:46');
INSERT INTO `email_templates` VALUES (12, 12, 'Default 7-Day Abandoned Cart Reminder', 'support@example.com', 'Online Store', '', 'Your cart is waiting for you! Take another look', '', '', '', 0, 'Dear {{customer_name}},', 1, '<p><strong>Items in your cart are still available!</strong></p><p>It\'s been a week since you added items to your cart. Complete your order before items sell out!</p>', '<p>Here is what is waiting in your cart:</p><p>{{cart_items_table}}</p><p><a href=\"{{checkout_url}}\" style=\"display:inline-block; background-color:#4f46e5; color:#ffffff; font-weight:bold; padding:12px 24px; border-radius:8px; text-decoration:none;\">Return to Cart &rarr;</a></p>', 'Sincerely,', 'Sales Department', 'If you have any questions or need help with your order, please reply to this email.', 'Copyright 2026', '', '', 0, '', 1, '2026-08-06 03:34:11', '2026-08-06 03:34:11');
