INSERT INTO `plugin_options` VALUES (248, 12, 'default_css', 'Default Plugin CSS (Read-Only Reference)', 'text-only', NULL, '/* Live Search 2026 Default Formatting */\n.live-search-2026-wrapper {\n    position: relative;\n    width: 100%;\n}\n.live-search-form {\n    display: flex;\n    align-items: stretch;\n    width: 100%;\n    background-color: #ffffff;\n    border: 1px solid #cbd5e1;\n    border-radius: 0.75rem;\n    overflow: hidden;\n}\n.live-search-form input[type=\"text\"] {\n    width: 100%;\n    max-width: 250px;\n    padding: 0.75rem 1rem;\n    border: none;\n    outline: none;\n    font-size: 0.875rem;\n}\n.live-search-form button[type=\"submit\"] {\n    padding: 0.75rem 1.5rem;\n    background-color: #4f46e5;\n    color: #ffffff;\n    font-weight: 700;\n    border: none;\n    border-top-left-radius: 0px !important;\n    border-bottom-left-radius: 0px !important;\n    border-top-right-radius: 0.75rem;\n    border-bottom-right-radius: 0.75rem;\n    cursor: pointer;\n}\n.live-search-form button[type=\"submit\"]:hover {\n    background-color: #4338ca;\n}', NULL, NULL, NULL, NULL, NULL, 'no', NULL, NULL, 55);
