INSERT INTO `plugin_settings` VALUES (1, 1, 'custom_css', '.slideshow-plugin-heading { font-size: 2.5rem; font-weight: 700; color: #fff; text-shadow: none; margin-bottom: 0.5rem; }\n.slideshow-plugin-subheading { font-size: 1.2rem; font-weight: 400; color: #fff; text-shadow: none; margin-bottom: 1.5rem; }\n.slideshow-plugin-btn { display: inline-block; padding: 12px 28px; background: #1E3A8A; color: #fff; border-radius: 8px; font-weight: 600; text-decoration: none; transition: background 0.2s; }\n.slideshow-plugin-btn:hover { background: #172554 }');
INSERT INTO `plugin_settings` VALUES (2, 1, 'default_css', '.slideshow-plugin-wrapper { width: 100%; }\n.slideshow-plugin-slide { min-height: 500px; background-size: cover; background-position: center; position: relative; }\n.slideshow-plugin-overlay { position: absolute; top: 0; left: 0; right: 0; bottom: 0; display: flex; padding: 40px; }\n.slideshow-plugin-content { max-width: 600px; }\n.slideshow-plugin-heading { font-size: 2.5rem; font-weight: 700; color: #fff; text-shadow: 0 2px 4px rgba(0,0,0,0.5); margin-bottom: 0.5rem; }\n.slideshow-plugin-subheading { font-size: 1.2rem; font-weight: 400; color: #fff; text-shadow: 0 1px 3px rgba(0,0,0,0.4); margin-bottom: 1.5rem; }\n.slideshow-plugin-btn { display: inline-block; padding: 12px 28px; background: #4f46e5; color: #fff; border-radius: 8px; font-weight: 600; text-decoration: none; transition: background 0.2s; }\n.slideshow-plugin-btn:hover { background: #4338ca; }\n@media (max-width: 768px) { .slideshow-plugin-slide { min-height: 300px; } .slideshow-plugin-heading { font-size: 1.5rem; } .slideshow-plugin-subheading { font-size: 1rem; } .slideshow-plugin-overlay { padding: 20px; } }');
