INSERT INTO `plugin_settings` VALUES (85, 7, 'custom_css', '/* Reduce slide spacing */\n.brands-plugin-slider-outer .swiper-wrapper {\n    align-items: center;\n}\n\n/* Shrink card top/bottom padding */\n.brand-slide-card {\n    padding: 6px 8px;\n}\n\n/* Make logo images taller */\n.brand-logo-img {\n    height: 65px;\n    max-height: 65px;\n}\n\n.dark .brand-logo-img {\n    filter: invert(1) grayscale(100%);\n    opacity: 0.45;\n    transition: filter 0.3s ease, opacity 0.3s ease;\n}\n.dark .brand-slide-card:hover .brand-logo-img {\n    filter: invert(1) grayscale(0%);\n    opacity: 1;\n}');
INSERT INTO `plugin_settings` VALUES (86, 7, 'default_css', '.brands-plugin-wrapper{width:100%}.brands-plugin-grid{display:grid;gap:1rem;padding:.5rem 0}.brands-plugin-card img{filter:grayscale(100%);transition:filter .3s ease}.brands-plugin-card:hover img{filter:grayscale(0%)}@media(max-width:767px){.brands-plugin-grid{grid-template-columns:repeat(2,minmax(0,1fr))!important}}@media(max-width:479px){.brands-plugin-grid{grid-template-columns:repeat(1,minmax(0,1fr))!important}}');
