INSERT INTO `plugins` VALUES (1, NULL, 'Slideshow - Swiper Display (2026)', '1.0', 'display', 'Built-in', 'slideshow_2026', 1, 'Displays an active slideshow using Swiper.js with full overlay content controls, flexible alignment, and CSS customizations.', 'slideshow-2026', 'no', NULL, NULL, NULL, '<p>Add the shortcode <strong>[plugin:slideshow-2026]</strong> to any CMS page to display your slideshow. To specify a slideshow by ID use: <strong>[plugin:slideshow-2026 id=2]</strong>. To disable navigation arrows: <strong>[plugin:slideshow-2026 nav=off]</strong>. To disable pagination dots: <strong>[plugin:slideshow-2026 paging=off]</strong>.</p>', NULL, NULL, NULL, 1, NULL, NULL, '2026-08-10 01:52:56', '2026-08-10 01:52:56');
INSERT INTO `plugins` VALUES (2, NULL, 'Shipping Rates - FedEx REST API (2026)', '1.0', 'shipping', 'Built-in', 'fedex_api_2026', 1, 'Live FedEx shipping rates via the FedEx REST API v1 for North American and International shipments.', 'fedex-api', 'no', NULL, NULL, NULL, '<p>Enter your FedEx API credentials below. You need a FedEx developer account with REST API credentials (Client ID and Client Secret). Visit <a href=\"https://developer.fedex.com\" target=\"_blank\">developer.fedex.com</a>. Note: This uses FedEx REST API v1 — old SOAP credentials are not compatible.</p>', NULL, NULL, NULL, 0, NULL, NULL, '2026-08-10 01:52:56', '2026-08-10 01:52:56');
INSERT INTO `plugins` VALUES (3, NULL, 'Shipping Rates - UPS REST API (2026)', '1.0', 'shipping', 'Built-in', 'ups_api_2026', 1, 'Real-time UPS shipping rates via the UPS REST Rating API with OAuth2. Supports all domestic and international UPS services.', 'ups-api', 'yes', '<p>Enter your <strong>UPS Client ID</strong> and <strong>Client Secret</strong> from <a href=\"https://developer.ups.com\" target=\"_blank\">developer.ups.com</a> and click Activate. Your UPS Account Number is optional but required for negotiated rates.</p>', 'Could not activate. Please check your UPS Client ID and Client Secret.', 'UPS plugin activated. Configure your services in the Settings tab.', '<p>Active UPS shipping rates will automatically appear on the checkout review page alongside other shipping options, sorted by price. No shortcode required for shipping plugins.</p>', NULL, 'https://developer.ups.com/api/reference/rating/business-rules', NULL, 0, NULL, NULL, '2026-08-10 01:52:56', '2026-08-10 01:52:56');
INSERT INTO `plugins` VALUES (4, NULL, 'Shipping Rates - USPS REST API v3 (2026)', '1.0', 'shipping', 'Built-in', 'usps_api_2026', 1, 'Real-time USPS shipping rates via the new USPS REST API v3 with OAuth2. Replaces the deprecated SOAP Web Tools. Supports Priority Mail, Ground Advantage, First-Class, and international services.', 'usps-api', 'yes', '<p>Register at <a href=\"https://developer.usps.com\" target=\"_blank\">developer.usps.com</a>, create an application, and copy your <strong>Client ID</strong> and <strong>Client Secret</strong>. Enter them below and click Activate.</p><p><em>Note: The old USPS Web Tools XML API was deprecated January 2024. This plugin uses the new REST API.</em></p>', 'Could not activate. Please verify your USPS Client ID and Client Secret.', 'USPS plugin activated. Enable your desired services in the Settings tab.', '<p>Active USPS shipping rates will automatically appear on the checkout review page alongside other shipping options, sorted by price. No shortcode required for shipping plugins.</p>', NULL, 'https://developer.usps.com/api/81', NULL, 0, NULL, NULL, '2026-08-10 01:52:56', '2026-08-10 01:52:56');
INSERT INTO `plugins` VALUES (5, NULL, 'Featured Items Display (2026)', '1.0', 'display', 'Built-in', 'featured_items_2026', 1, 'Displays products that have the Featured Item flag enabled. Supports grid, list, and Swiper slider display modes. Shortcode: [plugin:featured-items]', 'featured-items', 'no', NULL, NULL, NULL, '<p>Add <strong>[plugin:featured-items]</strong> to any CMS page to display your featured products. Available parameters:</p><ul><li><strong>display</strong> — <code>grid</code> (default), <code>list</code>, or <code>slider</code></li><li><strong>max</strong> — maximum number of products to show (default: 12)</li><li><strong>cols</strong> — grid columns 2–6 (default: 4, grid mode only)</li><li><strong>sort</strong> — <code>random</code>, <code>newest</code>, or <code>name</code></li><li><strong>header</strong> — optional section title text</li><li><strong>slides</strong> — visible slides at desktop (default: 4, slider mode only)</li><li><strong>nav</strong> — <code>on</code> / <code>off</code> navigation arrows (slider mode)</li><li><strong>autoplay</strong> — <code>on</code> / <code>off</code> (slider mode)</li><li><strong>speed</strong> — autoplay delay in ms (default: 4000, slider mode)</li></ul><p>To mark a product as featured, open the product in Admin → Edit → Advanced Settings and enable the ★ Featured Item toggle, then save.</p>', NULL, NULL, NULL, 1, NULL, NULL, '2026-08-10 01:52:56', '2026-08-10 01:52:56');
INSERT INTO `plugins` VALUES (6, NULL, 'Cross-Sell List Display (2026)', '1.0', 'display', 'Built-in', 'cross_sell_list_2026', 1, 'Displays the cross-selling products linked to a specific product. Filter by Product ID. Supports grid, list, and Swiper slider display modes. Shortcode: [plugin:cross-sell-list product_id=X]', 'cross-sell-list', 'no', NULL, NULL, NULL, '<p>Add <strong>[plugin:cross-sell-list product_id=X]</strong> to any CMS page to display the cross-sell products for a given product. Replace <code>X</code> with the numeric product ID. Available parameters:</p><ul><li><strong>product_id</strong> — the product whose cross-sells to display (required)</li><li><strong>display</strong> — <code>grid</code> (default), <code>list</code>, or <code>slider</code></li><li><strong>max</strong> — maximum number of products to show (default: 12)</li><li><strong>cols</strong> — grid columns 2–6 (default: 4, grid mode only)</li><li><strong>sort</strong> — <code>sort_order</code> (default), <code>newest</code>, or <code>name</code></li><li><strong>header</strong> — optional section title text</li><li><strong>slides</strong> — visible slides at desktop (default: 4, slider mode only)</li><li><strong>nav</strong> — <code>on</code> / <code>off</code> navigation arrows (slider mode)</li><li><strong>autoplay</strong> — <code>on</code> / <code>off</code> (slider mode)</li><li><strong>speed</strong> — autoplay delay in ms (default: 4000, slider mode)</li></ul><p>Cross-sells are managed per product under Admin → Edit Product → Cross-Selling. Only items with <em>Display on Item View</em> enabled will appear.</p>', NULL, NULL, NULL, 1, NULL, NULL, '2026-08-10 01:52:56', '2026-08-10 01:52:56');
INSERT INTO `plugins` VALUES (7, NULL, 'Brands Display (2026)', '1.0', 'display', 'Built-in', 'brands_2026', 1, 'Displays brand logos and links to brand SEO slugs in Slider, Grid, or List mode. Shortcode: [plugin:brands-2026]', 'brands-2026', 'no', NULL, NULL, NULL, '<p>Add <strong>[plugin:brands-2026]</strong> to any page. Options: <code>display=slider|grid|list</code>, <code>max=12</code>, <code>cols=4</code>, <code>header=\"Featured Brands\"</code>, <code>autoplay=on|off</code>, <code>show_label=1|0</code> (show/hide text brand name under logo).</p>', NULL, NULL, NULL, 1, NULL, NULL, '2026-08-10 01:52:56', '2026-08-10 01:52:56');
INSERT INTO `plugins` VALUES (8, NULL, 'Top Level Categories Display (2026)', '1.0', 'display', 'Built-in', 'categories_2026', 1, 'Displays TOP LEVEL categories only with image, name, and link to category SEO slug. Shortcode: [plugin:categories-2026]', 'categories-2026', 'no', NULL, NULL, NULL, '<p>Add <strong>[plugin:categories-2026]</strong> to any page. Options: <code>display=grid|slider|list</code>, <code>max=12</code>, <code>cols=4</code>, <code>header=\"Top Categories\"</code>.</p>', NULL, NULL, NULL, 1, NULL, NULL, '2026-08-10 01:52:56', '2026-08-10 01:52:56');
INSERT INTO `plugins` VALUES (9, NULL, 'Site News Flash Banner (2026)', '1.0', 'display', 'Built-in', 'newsflash_2026', 1, 'Renders an announcement news flash ticker banner. Shortcode: [plugin:newsflash-2026]', 'newsflash-2026', 'no', NULL, NULL, NULL, '<p>Add <strong>[plugin:newsflash-2026]</strong> to any header or page section. Options: <code>message=\"Announcement Text\"</code>, <code>bg_color=\"#4f46e5\"</code>, <code>text_color=\"#ffffff\"</code>, <code>dismissible=on</code>.</p>', NULL, NULL, NULL, 1, NULL, NULL, '2026-08-10 01:52:56', '2026-08-10 01:52:56');
INSERT INTO `plugins` VALUES (10, NULL, 'Testimonials Display (2026)', '1.0', 'display', 'Built-in', 'testimonials_2026', 1, 'Renders testimonials from the CMS testimonials table in Slider or List view with ratings and quote icons. Shortcode: [plugin:testimonials-2026]', 'testimonials-2026', 'no', NULL, NULL, NULL, '<p>Add <strong>[plugin:testimonials-2026]</strong> to any page. Options: <code>display=slider|list</code>, <code>max=6</code>, <code>cols=3</code>, <code>quote_icon=quote-left|none</code>, <code>header=\"What Our Customers Say\"</code>.</p>', NULL, NULL, NULL, 1, NULL, NULL, '2026-08-10 01:52:56', '2026-08-10 01:52:56');
INSERT INTO `plugins` VALUES (11, NULL, 'Social Media Icons (2026)', '1.0', 'display', 'Built-in', 'social_icons_2026', 1, 'Renders social media profile links with optional Font-Awesome 6 CDN integration. Shortcode: [plugin:social-icons-2026]', 'social-icons-2026', 'no', NULL, NULL, NULL, '<p>Add <strong>[plugin:social-icons-2026]</strong> to any page or footer block. Options: <code>align=left|center|right</code>, <code>size=sm|md|lg</code>, <code>font_awesome=on|off</code>.</p>', NULL, NULL, NULL, 1, NULL, NULL, '2026-08-10 01:52:56', '2026-08-10 01:52:56');
INSERT INTO `plugins` VALUES (12, NULL, 'Live Search Display (2026)', '1.0', 'display', 'Built-in', 'live_search_2026', 1, 'Multi-content live search input and results display for active Products, CMS Pages, KB Articles, and Testimonials. Shortcode: [plugin:live-search-2026]', 'live-search-2026', 'no', NULL, NULL, NULL, '<p>Add <strong>[plugin:live-search-2026]</strong> to render a search bar widget. To render search results on a page, use: <strong>[plugin:live-search-2026 mode=results]</strong>. Options: <code>placeholder=\"...\"</code>, <code>button_label=\"...\"</code>, <code>layout=list|grid</code>, <code>custom_css=\"...\"</code>, <code>custom_js=\"...\"</code>.</p>', NULL, NULL, NULL, 1, NULL, NULL, '2026-08-10 01:52:56', '2026-08-10 01:52:56');
INSERT INTO `plugins` VALUES (13, NULL, 'Events Calendar Display (2026)', '1.0', 'display', 'Built-in', 'events_calendar_2026', 1, 'Interactive events calendar displaying products marked as events based on start and stop dates. Shortcode: [plugin:events-calendar-2026]', 'events-calendar-2026', 'no', NULL, NULL, NULL, '<p>Add <strong>[plugin:events-calendar-2026]</strong> to any page. Options: <code>layout=month|list|grid</code>, <code>max=50</code>, <code>header=\"Upcoming Events\"</code>, <code>category=\"slug\"</code>.</p>', NULL, NULL, NULL, 1, NULL, NULL, '2026-08-10 01:52:56', '2026-08-10 01:52:56');
INSERT INTO `plugins` VALUES (14, NULL, 'FAQ Accordion Display (2026)', '1.0', 'display', 'Built-in', 'FaqsPlugin', 1, 'Renders frequently asked questions in an interactive Alpine.js accordion layout. Shortcode: [plugin:faqs-2026]', 'faqs-2026', 'no', NULL, NULL, NULL, '<p>Add <strong>[plugin:faqs-2026]</strong> to any CMS page. Available options:</p><ul><li><code>header=\"Frequently Asked Questions\"</code> — Section header title</li><li><code>show_header=1|0</code> — Show or hide the section header</li><li><code>open_first=1|0</code> — Open first FAQ item automatically on load</li><li><code>allow_multiple=1|0</code> — Allow multiple FAQ items open at once</li><li><code>max=0</code> — Maximum number of FAQs to display (0 for all)</li></ul>', NULL, NULL, NULL, 1, NULL, NULL, '2026-08-10 01:52:56', '2026-08-10 01:52:56');
INSERT INTO `plugins` VALUES (15, NULL, 'Order Status Tracker (2026)', '1.0', 'display', 'Built-in', 'order_tracker_2026', 1, 'Front-end order lookup widget allowing customers to enter order number and email to view current fulfillment status and items on the same page. Shortcode: [plugin:order-tracker-2026]', 'order-tracker-2026', 'no', NULL, NULL, NULL, '<p>Add <strong>[plugin:order-tracker-2026]</strong> to any CMS page to display the order status tracking form. Custom parameter override: <code>[plugin:order-tracker-2026 header=\"Track Your Order\"]</code>.</p>', NULL, NULL, NULL, 1, NULL, NULL, '2026-08-10 01:52:56', '2026-08-10 01:52:56');
INSERT INTO `plugins` VALUES (16, NULL, 'CMS Modal Display', '1.0', 'display', 'Built-in', 'modal_display', 1, 'Renders a CMS Modal popup by ID. Supports auto-open, trigger selectors, cookie lifetime, and position (center, left, right, bottom).', 'modal', 'no', NULL, NULL, NULL, '<p>Add <strong>[plugin:modal id=1]</strong> to any CMS page to render a modal by its ID. The modal must be active in the CMS Modals manager.</p>', NULL, NULL, NULL, 1, NULL, NULL, '2026-08-10 01:52:56', '2026-08-10 01:52:56');
