INSERT INTO `testimonial_translations` VALUES (1, 1, 2, '¡Este es un gran sitio web de compras! He pedido dos veces en el pasado y volveré a pedir en el futuro. ¡Gran precio, grandes artículos, gran servicio al cliente!', 'Comprador Verificado', NULL, NULL, 'ai_translated', '2026-08-10 16:12:57', '2026-08-05 19:52:43', '2026-08-10 16:12:59');
INSERT INTO `testimonial_translations` VALUES (2, 2, 2, 'Siempre tiene los mejores precios y el envío más rápido. Recomiendo encarecidamente esta empresa y continuaré usándola para futuros pedidos.', 'Cliente Regular', NULL, NULL, 'ai_translated', '2026-08-10 16:12:59', '2026-08-05 19:52:44', '2026-08-10 16:13:00');
INSERT INTO `testimonial_translations` VALUES (3, 3, 2, 'Este es un gran sitio web de tienda. Siempre tienen lo que necesito para regalos corporativos y promociones de temporada.', 'Propietario de Negocio', NULL, NULL, 'ai_translated', '2026-08-10 16:13:00', '2026-08-05 19:52:46', '2026-08-10 16:13:02');
INSERT INTO `testimonial_translations` VALUES (4, 4, 2, 'Una plataforma de comercio electrónico excepcional que ofrece artículos de alta calidad con un soporte al cliente impecable.', 'Revisor de Productos', NULL, NULL, 'ai_translated', '2026-08-10 16:13:02', '2026-08-05 19:52:48', '2026-08-10 16:13:04');
INSERT INTO `testimonial_translations` VALUES (5, 1, 3, 'C\'est un excellent site de shopping ! J\'ai commandé deux fois dans le passé et je commanderai à nouveau à l\'avenir. Excellent prix, excellents articles, excellent service client !', 'Acheteur Vérifié', NULL, NULL, 'ai_translated', '2026-08-10 17:17:26', '2026-08-06 16:09:10', '2026-08-10 17:17:28');
INSERT INTO `testimonial_translations` VALUES (6, 2, 3, 'A toujours les meilleurs prix et la livraison la plus rapide. Je recommande vivement cette entreprise et continuerai à l\'utiliser pour mes futures commandes.', 'Client Régulier', NULL, NULL, 'ai_translated', '2026-08-10 17:17:28', '2026-08-06 16:09:12', '2026-08-10 17:17:30');
INSERT INTO `testimonial_translations` VALUES (7, 3, 3, 'C\'est un excellent site de magasin. Ils ont toujours ce dont j\'ai besoin pour les cadeaux d\'entreprise et les promotions saisonnières.', 'Propriétaire d\'entreprise', NULL, NULL, 'ai_translated', '2026-08-10 17:17:30', '2026-08-06 16:09:13', '2026-08-10 17:17:31');
INSERT INTO `testimonial_translations` VALUES (8, 4, 3, 'Une plateforme de commerce électronique exceptionnelle offrant des articles de haute qualité avec un support client irréprochable.', 'Critique de produit', NULL, NULL, 'ai_translated', '2026-08-10 17:17:31', '2026-08-06 16:09:15', '2026-08-10 17:17:33');
